export type Lock = {
  owner: string;
  session: string;
  timestamp: string; // ISO
  ttl_seconds: number;
  files: string[];
  intent?: string;
};

import * as fs from "fs";
import * as path from "path";

const repoRoot = process.cwd();
const lockPath = path.join(repoRoot, ".ai-lock.json");

function _nowISO() {
  return new Date().toISOString();
}

export function readLock(): Lock | null {
  try {
    const raw = fs.readFileSync(lockPath, "utf8");
    return JSON.parse(raw) as Lock;
  } catch (_e) { void _e; void _e;
    return null;
  }
}

export function isLockStale(lock: Lock): boolean {
  const ts = new Date(lock.timestamp).getTime();
  const expires = ts + lock.ttl_seconds * 1000;
  return Date.now() > expires;
}

export function acquireLock(lock: Lock): boolean {
  // simple atomic write by writing to temp and renaming
  const tmp = lockPath + "." + Math.random().toString(36).slice(2);
  try {
    if (fs.existsSync(lockPath)) return false;
    fs.writeFileSync(tmp, JSON.stringify(lock, null, 2), "utf8");
    fs.renameSync(tmp, lockPath);
    return true;
  } catch {
    try {
      if (fs.existsSync(tmp)) fs.unlinkSync(tmp);
    } catch (_e) { void _e; void _e; }
    return false;
  }
}

export function releaseLock(): boolean {
  try {
    if (fs.existsSync(lockPath)) fs.unlinkSync(lockPath);
    return true;
  } catch {
    return false;
  }
}

export function appendAudit(entry: unknown) {
  // entry is intentionally untyped here; serialize best-effort
  const safeEntry: any = entry as any;
  const dir = path.join(repoRoot, ".ai-history");
  if (!fs.existsSync(dir)) fs.mkdirSync(dir);
  const fname = path.join(
    dir,
    Date.now() + "-" + (safeEntry?.owner || "unknown") + ".json",
  );
  fs.writeFileSync(fname, JSON.stringify(safeEntry, null, 2), "utf8");
}

import type { Vector3, EntityId } from '../../types/index.js';

/**
 * Physics body properties for creating new bodies
 */
export interface BodyProps {
  position: Vector3;
  velocity?: Vector3;
  mass?: number;
  radius?: number;
  isStatic?: boolean;
  collisionMask?: number;
}

/**
 * Physics body state for querying/updating
 */
export interface BodyState {
  position: Vector3;
  velocity: Vector3;
  mass: number;
  radius: number;
}

/**
 * Raycast hit result
 */
export interface RaycastHit {
  entityId: EntityId;
  point: Vector3;
  normal: Vector3;
  distance: number;
}

/**
 * Sweep hit result for moving objects
 */
export interface SweepHit {
  entityId: EntityId;
  point: Vector3;
  normal: Vector3;
  distance: number;
  time: number; // [0,1] time along sweep
}

/**
 * Axis-aligned bounding box
 */
export interface AABB {
  min: Vector3;
  max: Vector3;
}

/**
 * Physics event types
 */
export interface PhysicsEvent {
  type: 'collision' | 'sleep' | 'wake';
  entityIds: EntityId[];
  point?: Vector3;
  normal?: Vector3;
  impulse?: number;
}

/**
 * Disposable interface for event subscriptions
 */
export interface Disposable {
  dispose(): void;
}

/**
 * Enhanced PhysicsAdapter providing comprehensive physics operations
 * for simulation determinism, queries, and body management.
 */
export interface PhysicsAdapter {
  initDone: boolean;
  world?: any;

  // Core simulation
  step(dt: number, opts?: { iterations?: number; substeps?: number }): void;
  getLastStepInfo(): { dt: number; iterations: number; substeps: number };
  dispose(): void;

  // Collision and overlap queries
  raycast(from: Vector3, to: Vector3, mask?: number): RaycastHit | null;
  sweepSphere(center: Vector3, radius: number, dir: Vector3, maxDist: number, mask?: number): SweepHit | null;
  overlapAABB(aabb: AABB, mask?: number): EntityId[];

  // Body management
  addBody(entityId: EntityId, props: BodyProps): void;
  removeBody(entityId: EntityId): void;
  setBodyState(entityId: EntityId, state: Partial<BodyState>): void;
  getBodyState(entityId: EntityId): BodyState | null;

  // Forces and impulses
  applyImpulse(entityId: EntityId, impulse: Vector3): void;
  applyForce(entityId: EntityId, force: Vector3): void;

  // Events
  on(event: 'collision' | 'sleep' | 'wake', handler: (e: PhysicsEvent) => void): Disposable;
}

/**
 * No-op physics adapter for tests and headless runs.
 */
export class NoopPhysicsAdapter implements PhysicsAdapter {
  initDone = true;
  private lastStep = { dt: 0, iterations: 0, substeps: 0 };
  private eventHandlers = new Map<string, ((e: PhysicsEvent) => void)[]>();

  step(dt: number, opts?: { iterations?: number; substeps?: number }): void {
    this.lastStep = {
      dt,
      iterations: opts?.iterations ?? 1,
      substeps: opts?.substeps ?? 1,
    };
  }

  getLastStepInfo() {
    return { ...this.lastStep };
  }

  dispose(): void {
    this.eventHandlers.clear();
  }

  raycast(_from: Vector3, _to: Vector3, _mask?: number): RaycastHit | null {
    return null;
  }

  sweepSphere(_center: Vector3, _radius: number, _dir: Vector3, _maxDist: number, _mask?: number): SweepHit | null {
    return null;
  }

  overlapAABB(_aabb: AABB, _mask?: number): EntityId[] {
    return [];
  }

  addBody(_entityId: EntityId, _props: BodyProps): void {}
  removeBody(_entityId: EntityId): void {}
  setBodyState(_entityId: EntityId, _state: Partial<BodyState>): void {}
  getBodyState(_entityId: EntityId): BodyState | null {
    return null;
  }

  applyImpulse(_entityId: EntityId, _impulse: Vector3): void {}
  applyForce(_entityId: EntityId, _force: Vector3): void {}

  on(event: 'collision' | 'sleep' | 'wake', handler: (e: PhysicsEvent) => void): Disposable {
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, []);
    }
    this.eventHandlers.get(event)!.push(handler);
    
    return {
      dispose: () => {
        const handlers = this.eventHandlers.get(event);
        if (handlers) {
          const index = handlers.indexOf(handler);
          if (index >= 0) {
            handlers.splice(index, 1);
          }
        }
      }
    };
  }
}

import type { AIPersonality, AIIntent } from '../../config/behaviorConfig.js';
import type { Ship, RNG } from '../../types/index.js';

export type ComputeOptions = {
  // If true, adjust the base duration using the provided evade duration
  // before adding the random range (parity with current controller logic).
  damageEvade?: boolean;
  damageEvadeDuration?: number; // required when damageEvade is true
};

/**
 * IntentManager — small helper to compute and apply intent lifetimes.
 * Keeps exact parity with the legacy logic in AIController:
 *   base = minIntentDuration
 *   if (damageEvade) base = min(base, damageEvadeDuration)
 *   final = base + rng.next() * (max - min)
 */
export class IntentManager {
  computeDuration(personality: AIPersonality, rng: RNG, opts?: ComputeOptions): number {
    const baseMin = personality.minIntentDuration;
    const range = personality.maxIntentDuration - personality.minIntentDuration;
    let base = baseMin;
    if (opts?.damageEvade && typeof opts.damageEvadeDuration === 'number') {
      base = Math.min(base, opts.damageEvadeDuration);
    }
    return base + rng.next() * range;
  }

  /**
   * Applies the intent to the ship and sets intentEndTime using computeDuration.
   * Returns the assigned duration for convenience.
   */
  applyIntent(
    ship: Ship,
    now: number,
    intent: AIIntent,
    personality: AIPersonality,
    rng: RNG,
    opts?: ComputeOptions
  ): number {
    const duration = this.computeDuration(personality, rng, opts);
    if (!ship.aiState) ship.aiState = {} as any;
    const aiState = ship.aiState!;
    aiState.currentIntent = intent;
    aiState.intentEndTime = now + duration;
    return duration;
  }
}

import type { Vector3, SimBounds, Ship, RNG } from '../../types/index.js';
import type { BehaviorConfig } from '../../config/behaviorConfig.js';
import { lookAt, getForwardVector, angleDifference, clampTurn } from '../../utils/vector3.js';
import { PhysicsConfig } from '../../config/physicsConfig.js';

export type RandomFn = () => number; // [0,1)

// Calculate safety score for an escape position. Higher score = safer.
export function calculateEscapeScore(
  shipPos: Vector3,
  targetPos: Vector3,
  threats: readonly Vector3[],
  friendlies: readonly Vector3[],
  bounds: SimBounds,
  settings: BehaviorConfig['globalSettings']
): number {
  let score = settings.evadeBaseScore;

  // Threat proximity penalty
  for (const t of threats) {
    const dx = targetPos.x - t.x;
    const dy = targetPos.y - t.y;
    const dz = targetPos.z - t.z;
    const dist = Math.hypot(dx, dy, dz);
    const threatPenalty = Math.max(0, 200 - dist) * settings.evadeThreatPenaltyWeight;
    score -= threatPenalty;
  }

  // Boundary penalties
  const m = settings.boundarySafetyMargin;
  if (targetPos.x < m) score -= (m - targetPos.x) * settings.evadeBoundaryPenaltyWeight;
  if (targetPos.x > bounds.width - m) score -= (targetPos.x - (bounds.width - m)) * settings.evadeBoundaryPenaltyWeight;
  if (targetPos.y < m) score -= (m - targetPos.y) * settings.evadeBoundaryPenaltyWeight;
  if (targetPos.y > bounds.height - m) score -= (targetPos.y - (bounds.height - m)) * settings.evadeBoundaryPenaltyWeight;
  if (targetPos.z < m) score -= (m - targetPos.z) * settings.evadeBoundaryPenaltyWeight;
  if (targetPos.z > bounds.depth - m) score -= (targetPos.z - (bounds.depth - m)) * settings.evadeBoundaryPenaltyWeight;

  // Distance improvement bonus relative to nearest threat (assume first is nearest if provided)
  if (threats.length > 0) {
    const t = threats[0];
    const cdx = shipPos.x - t.x;
    const cdy = shipPos.y - t.y;
    const cdz = shipPos.z - t.z;
    const currentDistance = Math.hypot(cdx, cdy, cdz);
    const ndx = targetPos.x - t.x;
    const ndy = targetPos.y - t.y;
    const ndz = targetPos.z - t.z;
    const newDistance = Math.hypot(ndx, ndy, ndz);
    if (newDistance > currentDistance) {
      score += (newDistance - currentDistance) * settings.evadeDistanceImprovementWeight;
    }
  }

  // Friendly collision penalty
  for (const f of friendlies) {
    const dx = targetPos.x - f.x;
    const dy = targetPos.y - f.y;
    const dz = targetPos.z - f.z;
    const dist = Math.hypot(dx, dy, dz);
    if (dist < settings.friendlyAvoidanceDistance) {
      score -= (settings.friendlyAvoidanceDistance - dist) * settings.evadeFriendlyPenaltyWeight;
    }
  }

  return score;
}

// Pure-ish moveTowards: mutates ship based only on provided inputs. Boundary physics is intentionally excluded.
export function moveTowards(
  ship: Ship,
  targetPos: Vector3,
  dt: number,
  settings: BehaviorConfig['globalSettings'],
  speedOverride?: number
): void {
  const moveSpeed = speedOverride || ship.speed;
  // Desired direction
  const dx = targetPos.x - ship.pos.x;
  const dy = targetPos.y - ship.pos.y;
  const dz = targetPos.z - ship.pos.z;
  const distance = Math.hypot(dx, dy, dz);
  if (distance < settings.movementCloseEnoughThreshold) return;

  // Target orientation
  const targetOrientation = lookAt(ship.pos, targetPos);
  const pitchDiff = angleDifference(ship.orientation.pitch, targetOrientation.pitch);
  const yawDiff = angleDifference(ship.orientation.yaw, targetOrientation.yaw);
  const pitchTurn = clampTurn(pitchDiff, ship.turnRate * dt);
  const yawTurn = clampTurn(yawDiff, ship.turnRate * dt);
  ship.orientation.pitch += pitchTurn;
  ship.orientation.yaw += yawTurn;
  ship.dir = ship.orientation.yaw; // maintain legacy field

  // Advance velocity and position using PhysicsConfig
  const forward = getForwardVector(ship.orientation.pitch, ship.orientation.yaw);
  const accel = moveSpeed * PhysicsConfig.acceleration.forwardMultiplier;
  ship.vel.x += forward.x * accel * dt;
  ship.vel.y += forward.y * accel * dt;
  ship.vel.z += forward.z * accel * dt;

  ship.vel.x *= PhysicsConfig.speed.dampingFactor;
  ship.vel.y *= PhysicsConfig.speed.dampingFactor;
  ship.vel.z *= PhysicsConfig.speed.dampingFactor;

  const maxV = moveSpeed * PhysicsConfig.speed.maxSpeedMultiplier;
  const v = Math.hypot(ship.vel.x, ship.vel.y, ship.vel.z);
  if (v > maxV && v > 0) {
    ship.vel.x = (ship.vel.x / v) * maxV;
    ship.vel.y = (ship.vel.y / v) * maxV;
    ship.vel.z = (ship.vel.z / v) * maxV;
  }

  ship.pos.x += ship.vel.x * dt;
  ship.pos.y += ship.vel.y * dt;
  ship.pos.z += ship.vel.z * dt;
}

// Calculate separation force given neighbor positions. Returns unit vector and neighborCount.
export function calculateSeparationForceWithCount(
  shipPos: Vector3,
  neighbors: readonly Vector3[],
  separationDistance: number,
  magnitudeThreshold: number,
  random: RandomFn
): { force: Vector3; neighborCount: number } {
  let sx = 0, sy = 0, sz = 0;
  let count = 0;
  const sepDistSq = separationDistance * separationDistance;
  for (const n of neighbors) {
    const dx = shipPos.x - n.x;
    const dy = shipPos.y - n.y;
    const dz = shipPos.z - n.z;
    const distSq = dx*dx + dy*dy + dz*dz;
    if (distSq <= 0 || distSq >= sepDistSq) continue;
    const dist = Math.sqrt(distSq);
    const weight = (separationDistance - dist) / separationDistance;
    const inv = 1 / dist;
    sx += dx * weight * inv;
    sy += dy * weight * inv;
    sz += dz * weight * inv;
    count++;
  }

  if (count === 0) return { force: { x: 0, y: 0, z: 0 }, neighborCount: 0 };

  sx /= count; sy /= count; sz /= count;
  const mag = Math.hypot(sx, sy, sz);
  if (mag > magnitudeThreshold) {
    return { force: { x: sx / mag, y: sy / mag, z: sz / mag }, neighborCount: count };
  }

  // Symmetry fallback: push away from local center
  let cx = 0, cy = 0, cz = 0;
  for (const n of neighbors) {
    const dx = shipPos.x - n.x;
    const dy = shipPos.y - n.y;
    const dz = shipPos.z - n.z;
    const distSq = dx*dx + dy*dy + dz*dz;
    if (distSq > 0 && distSq < sepDistSq) {
      cx += n.x; cy += n.y; cz += n.z;
    }
  }
  if (cx !== 0 || cy !== 0 || cz !== 0) {
    const inv = 1 / count; cx *= inv; cy *= inv; cz *= inv;
    const rx = shipPos.x - cx;
    const ry = shipPos.y - cy;
    const rz = shipPos.z - cz;
    const rmag = Math.hypot(rx, ry, rz);
    if (rmag > magnitudeThreshold) {
      return { force: { x: rx / rmag, y: ry / rmag, z: rz / rmag }, neighborCount: count };
    }
  }

  // Last resort: small random vector to break symmetry
  const angle = random() * Math.PI * 2;
  return { force: { x: Math.cos(angle), y: Math.sin(angle), z: 0 }, neighborCount: count };
}

import type { GameState } from '../types/index.js';
import LRUAssetPool from './assetPool.js';
// AssetLoader scaffold: wraps three's GLTFLoader and caches in GameState.assetPool if present.

// Note: this file uses dynamic imports to avoid bundling three/examples heavy code at module eval.

export type AssetHandle = {
  url: string;
  data: any;
};

export async function loadGLTF(state: GameState, url: string): Promise<AssetHandle> {
  // Check cache
  try {
    const pool = (state as any).assetPool as Map<string, any> | undefined;
    if (pool) {
      const cached = pool.get(url);
      if (cached) return { url, data: cached };
    }
  } catch (e) { void e; void e; /* ignore */ }

  // Lazy-load three GLTF loader to keep startup light
  const mod = await import('three/examples/jsm/loaders/GLTFLoader.js');
  const GLTFLoader = (mod as any).GLTFLoader;
  const loader = new GLTFLoader();

  return new Promise((resolve, reject) => {
    try {
      loader.load(url, (gltf: any) => {
        // store in pool if available
        try {
          const pool = (state as any).assetPool as Map<string, any> | undefined;
          if (pool) pool.set(url, gltf);
        } catch (e) { void e; void e; /* ignore */ }
        resolve({ url, data: gltf });
      }, undefined, (err: any) => reject(err));
    } catch (e) { void e;reject(e);
    }
  });
}

import type { GameState, Ship, ShipClass, Team, Vector3, EntityId, Bullet, TurretState } from '../types/index.js';
import { DefaultSimConfig } from '../config/simConfig.js';
import { SHIP_CLASS_CONFIGS, getShipClassConfig } from '../config/entitiesConfig.js';
import { createRNG } from '../utils/rng.js';
import { nextLevelXp, XP_PER_DAMAGE, XP_PER_KILL, applyLevelUps } from '../config/progression.js';
import { DEFAULT_BEHAVIOR_CONFIG } from '../config/behaviorConfig.js';
import { AIController } from './aiController.js';
import { FleetConfig } from '../config/fleetConfig.js';
import { PhysicsConfig } from '../config/physicsConfig.js';
import { ShipVisualConfig } from '../config/shipVisualConfig.js';
import { CarrierSpawnConfig } from '../config/carrierSpawnConfig.js';
import { lookAt, getForwardVector, angleDifference, clampTurn } from '../utils/vector3.js';
import { SpatialGrid } from '../utils/spatialGrid.js';
import { findNearestEnemy as sharedFindNearestEnemy, findNearbyEnemies as sharedFindNearbyEnemies, findNearbyFriends as sharedFindNearbyFriends } from './searchUtils.js';
import { applyBoundaryPhysicsShip, applyBoundaryPhysicsBullet } from './boundaryUtils.js';

export function createInitialState(seed?: string): GameState {
  const config = { ...DefaultSimConfig };
  if (seed) {
    config.seed = seed;
  } else if (config.useTimeBasedSeed) {
    config.seed = `SPACE-${Date.now()}`;
  }

  const rng = createRNG(config.seed);
  const state: GameState = {
    time: 0,
    tick: 0,
    running: false,
    speedMultiplier: 1,
    rng,
    nextId: 1,
    simConfig: config,
    ships: [],
    shipIndex: new Map(),
    shipDataVersion: 0,
    bullets: [],
    score: { red: 0, blue: 0 },
    behaviorConfig: { ...DEFAULT_BEHAVIOR_CONFIG }
  };

  // Initialize spatial grid if enabled
  if (state.behaviorConfig?.globalSettings.enableSpatialIndex) {
    const bounds = {
      width: config.simBounds.width,
      height: config.simBounds.height,
      depth: config.simBounds.depth
    };
    state.spatialGrid = new SpatialGrid(config.spatialGrid.cellSize, bounds);
  }

  return state;
}

export function resetState(state: GameState, seed?: string) {
  const s = seed ?? state.rng.seed;
  const newRng = createRNG(s);
  state.time = 0;
  state.tick = 0;
  state.running = false;
  state.speedMultiplier = 1;
  state.rng = newRng;
  state.nextId = 1;
  state.ships = [];
  state.shipIndex = new Map();
  state.shipDataVersion = 0;
  state.bullets = [];
  state.score = { red: 0, blue: 0 };
  // Drop cached AI controller so it can be recreated lazily with fresh state/config
  state.aiController = undefined;
  // Reset behavior config to defaults
  state.behaviorConfig = { ...DEFAULT_BEHAVIOR_CONFIG };
  
  // Reset spatial grid if enabled
  if (state.behaviorConfig?.globalSettings.enableSpatialIndex) {
    const bounds = {
      width: state.simConfig.simBounds.width,
      height: state.simConfig.simBounds.height,
      depth: state.simConfig.simBounds.depth
    };
    state.spatialGrid = new SpatialGrid(state.simConfig.spatialGrid.cellSize, bounds);
  } else {
    state.spatialGrid = undefined;
  }
}

function allocateId(state: GameState): EntityId { return state.nextId++; }

export function spawnShip(state: GameState, team: Team, cls: ShipClass, pos?: Vector3, parentCarrierId?: EntityId): Ship {
  const cfg = getShipClassConfig(cls);
  const id = allocateId(state);
  const level = { level: 1, xp: 0, nextLevelXp: nextLevelXp(1) };
  const maxHealth = Math.floor(applyLevelUps(level.level, cfg.baseHealth));
  const maxShield = Math.floor(applyLevelUps(level.level, cfg.shield));
  const turrets: TurretState[] = cfg.turrets.map((t, i) => ({ id: `${t.id}-${i}`, cooldownLeft: 0 }));
  const p = pos ?? randomSpawnPos(state, team);
  // Initialize with random yaw, level pitch and roll for natural spawning
  const randomYaw = state.rng.next() * Math.PI * 2;
  
  const ship: Ship = {
    id, team, class: cls,
    pos: { x: p.x, y: p.y, z: p.z }, 
    vel: { x: 0, y: 0, z: 0 }, 
    orientation: {
      pitch: 0, // level flight initially
      yaw: randomYaw,
      roll: 0   // no banking initially
    },
    // Keep legacy dir field for backward compatibility
    dir: randomYaw,
    targetId: null,
    health: maxHealth, maxHealth,
    armor: cfg.armor,
    shield: maxShield, maxShield,
    shieldRegen: cfg.shieldRegen,
    speed: cfg.speed,
    turnRate: cfg.turnRate,
    turrets,
    kills: 0,
    level,
    spawnedFighters: cls === 'carrier' ? 0 : undefined,
    fighterSpawnCdLeft: cls === 'carrier' ? CarrierSpawnConfig.fighter.initialCooldown : undefined,
    parentCarrierId,
    // Initialize dirty flags to true for initial UI render
    _healthDirty: true,
    _shieldDirty: true,
  };
  // Optionally apply a tiny randomized velocity jitter at spawn to break perfect
  // symmetry in deterministic tests and initial cluster spawns. The magnitudes are
  // intentionally very small (fractional) and scale with ship speed so larger ships
  // get a slightly larger jitter but remain subtle in gameplay. This behavior can
  // be toggled via behaviorConfig.globalSettings.enableSpawnJitter.
  const enableJitter = state.behaviorConfig?.globalSettings.enableSpawnJitter;
  if (enableJitter) {
    const jitterScale = 0.02; // fraction of ship.speed per second
    const angle = state.rng.next() * Math.PI * 2;
    const jitterMag = ship.speed * jitterScale;
    ship.vel.x += Math.cos(angle) * jitterMag;
    ship.vel.y += Math.sin(angle) * jitterMag;
  }

  state.ships.push(ship);
  state.shipIndex?.set(ship.id, ship);
  // Increment version for efficient change detection
  state.shipDataVersion++;
  return ship;
}

function randomSpawnPos(state: GameState, team: Team): Vector3 {
  const margin = FleetConfig.spawning.margin;
  const y = state.rng.int(margin, state.simConfig.simBounds.height - margin);
  const z = state.rng.int(margin, state.simConfig.simBounds.depth - margin);
  const x = team === 'red' ? state.rng.int(margin, margin + FleetConfig.spawning.spawnWidth) : state.rng.int(state.simConfig.simBounds.width - margin - FleetConfig.spawning.spawnWidth, state.simConfig.simBounds.width - margin);
  return { x, y, z };
}

export function spawnFleet(state: GameState, team: Team, count = 5) {
  for (let i = 0; i < count; i++) {
    const cls = state.rng.pick(['fighter','corvette','frigate','destroyer','carrier'] as const);
    spawnShip(state, team, cls);
  }
}

// Delegate nearest-enemy lookup to shared search utilities (spatial-grid preferred)
function findNearestEnemy(state: GameState, ship: Ship): Ship | undefined {
  return sharedFindNearestEnemy(state, ship) || undefined;
}

function clamp(v: number, lo: number, hi: number) { return Math.max(lo, Math.min(hi, v)); }

/**
 * Apply boundary physics to a ship based on simulation configuration
 * This handles bounce, wrap, and remove behaviors consistently across AI systems
 */
export function applyBoundaryPhysics(ship: Ship, state: GameState) {
  // Keep compatibility API but delegate to centralized boundary utils for ships
  applyBoundaryPhysicsShip(ship, state);
}

function fireTurrets(state: GameState, ship: Ship, dt: number) {
  const target = ship.targetId ? state.ships.find(s => s.id === ship.targetId!) : undefined;
  for (const t of ship.turrets) {
    t.cooldownLeft = Math.max(0, t.cooldownLeft - dt);
  }
  if (!target) return;
  const cfg = getShipClassConfig(ship.class);
  const dx = target.pos.x - ship.pos.x; const dy = target.pos.y - ship.pos.y; const dz = target.pos.z - ship.pos.z;
  const dist = Math.hypot(dx, dy, dz);
  for (let i = 0; i < ship.turrets.length; i++) {
    const tState = ship.turrets[i];
    const tCfg = cfg.turrets[i % cfg.turrets.length];
    if (tState.cooldownLeft > 0) continue;
    if (dist > tCfg.range) continue;
    // Fire: create bullet towards target
    const id = state.nextId++;
    const dir = Math.atan2(dy, dx);
    const speed = tCfg.bulletSpeed;
    const bullet: Bullet = {
      id,
      ownerShipId: ship.id,
      ownerTeam: ship.team,
      pos: { x: ship.pos.x, y: ship.pos.y, z: ship.pos.z },
      vel: { x: Math.cos(dir) * speed, y: Math.sin(dir) * speed, z: 0 },
      ttl: 3,
      damage: tCfg.damage,
    };
    state.bullets.push(bullet);
    tState.cooldownLeft = tCfg.cooldown;
  }
}

function updateBullets(state: GameState, dt: number) {
  const { width, height, depth } = state.simConfig.simBounds;
  const behavior = state.simConfig.boundaryBehavior.bullets;

  for (const b of state.bullets) {
    b.ttl -= dt;
    b.pos.x += b.vel.x * dt;
    b.pos.y += b.vel.y * dt;
    b.pos.z += b.vel.z * dt;
  }

  // Handle bullet boundary conditions using shared helper
  for (const b of state.bullets) {
    if (b.ttl <= 0) continue;
    applyBoundaryPhysicsBullet(b, state);
    if (b.ttl <= 0) continue; // bullet removed by boundary behavior

    // Collisions (simple radius approx)
    for (const s of state.ships) {
      if (s.team === b.ownerTeam || s.health <= 0) continue;
      const dx = s.pos.x - b.pos.x; const dy = s.pos.y - b.pos.y; const dz = s.pos.z - b.pos.z;
      const d = Math.hypot(dx, dy, dz);
      const hitR = ShipVisualConfig.ships[s.class]?.collisionRadius ?? ShipVisualConfig.defaults.collisionRadius;
      if (d < hitR) {
        // Apply damage to shield first
        let dmgLeft = b.damage;
        let totalDamage = 0; // Track total damage for recent damage accumulator
        
        if (s.shield > 0) {
          const absorb = Math.min(s.shield, dmgLeft);
          s.shield -= absorb;
          dmgLeft -= absorb;
          totalDamage += absorb;
          // Track shield hit for visual effects
          s.lastShieldHitTime = state.time;
          // Record direction of impact on shield as a unit vector from ship center to bullet position
          const len = Math.max(1e-6, d);
          s.lastShieldHitDir = { x: dx / len, y: dy / len, z: dz / len };
          s.lastShieldHitStrength = absorb; // use absorbed shield damage as strength proxy
        }
        if (dmgLeft > 0) {
          // Armor reduces damage
          const effective = Math.max(1, dmgLeft - s.armor * 0.3);
          s.health -= effective;
          totalDamage += effective;
          // XP to owner
            // Cache owner lookup once per hit for efficiency
            const owner = state.shipIndex?.get(b.ownerShipId) ?? state.ships.find(sh => sh.id === b.ownerShipId);
            if (owner) {
              owner.level.xp += effective * XP_PER_DAMAGE;
              // Track last damage source for kill crediting (timestamped)
              s.lastDamageBy = owner.id;
              s.lastDamageTime = state.time;
            }
        }
        
        // Update recent damage tracking for AI
        if (s.aiState && totalDamage > 0) {
          s.aiState.recentDamage = (s.aiState.recentDamage || 0) + totalDamage;
          s.aiState.lastDamageTime = state.time;
        }
        
        // Bullet consumed
        b.ttl = 0;
        break;
      }
    }
  }
  // Remove dead bullets
  state.bullets = state.bullets.filter(b => b.ttl > 0);
}

function processDeathsAndXP(state: GameState) {
  for (const s of state.ships) {
    if (s.health <= 0 && s.maxHealth > 0) {
      // Credit kill to the last ship that damaged this ship within a short recent window
      let killer = null;
      if (s.lastDamageBy) {
        // Prefer recent damage within configurable window to avoid long-dead credit
        const recentWindow = state.behaviorConfig?.globalSettings.killCreditWindowSeconds ?? 5;
        if ((s.lastDamageTime ?? -Infinity) >= state.time - recentWindow) {
          killer = state.ships.find(sh => sh.id === s.lastDamageBy && sh.team !== s.team);
        }
      }
      // Fallback: approximate via target linking
      if (!killer) {
        killer = state.ships.find(sh => sh.targetId === s.id && sh.team !== s.team) ?? null;
      }
      if (killer) {
        killer.kills += 1;
        killer.level.xp += XP_PER_KILL;
        state.score[killer.team] += 1;
      }
      // If this was a fighter spawned by a carrier, decrement the carrier's alive counter
      if (s.parentCarrierId) {
        const carrier = state.ships.find(sh => sh.id === s.parentCarrierId);
        if (carrier && typeof carrier.spawnedFighters === 'number') {
          carrier.spawnedFighters = Math.max(0, (carrier.spawnedFighters ?? 0) - 1);
        }
      }
      // Mark as removed by setting maxHealth = 0 sentinel then filtered later
      s.maxHealth = 0;
    }
  }
  state.ships = state.ships.filter(s => s.maxHealth > 0);
  // Rebuild shipIndex for consistency (cheap relative to simulation sizes)
  if (state.shipIndex) {
    state.shipIndex.clear();
    for (const s of state.ships) state.shipIndex.set(s.id, s);
  }
  // Increment version when ships are removed
  state.shipDataVersion++;
}

function handleLevelUps(state: GameState) {
  for (const s of state.ships) {
    while (s.level.xp >= s.level.nextLevelXp) {
      s.level.xp -= s.level.nextLevelXp;
      s.level.level += 1;
      s.level.nextLevelXp = nextLevelXp(s.level.level);
      // Improve stats
      const cfg = getShipClassConfig(s.class);
      s.maxHealth = Math.floor(applyLevelUps(s.level.level, cfg.baseHealth));
      s.maxShield = Math.floor(applyLevelUps(s.level.level, cfg.shield));
      s.health = Math.min(s.maxHealth, s.health + Math.floor(s.maxHealth * 0.2));
      s.shield = s.maxShield; // refill on level
      
      // Mark as dirty for UI optimization
      s._healthDirty = true;
      s._shieldDirty = true;
    }
  }
}

function carrierSpawnLogic(state: GameState, dt: number) {
  for (const s of state.ships) {
    if (s.class !== 'carrier' || s.health <= 0) continue;
    if (s.fighterSpawnCdLeft === undefined) continue;
    s.fighterSpawnCdLeft = Math.max(0, (s.fighterSpawnCdLeft ?? 0) - dt);
    const cfg = getShipClassConfig('carrier');
    if ((s.spawnedFighters ?? 0) < (cfg.maxFighters ?? 0) && s.fighterSpawnCdLeft === 0) {
      // Use carrier's current yaw for spawning direction
      const angle = s.orientation.yaw + ((state.rng.next() - 0.5) * CarrierSpawnConfig.fighterSpawn.angleRandomization);
      const offset = { x: s.pos.x + Math.cos(angle) * CarrierSpawnConfig.fighterSpawn.offsetDistance, y: s.pos.y + Math.sin(angle) * CarrierSpawnConfig.fighterSpawn.offsetDistance, z: s.pos.z };
      const child = spawnShip(state, s.team, 'fighter', offset, s.id);
      child.vel.x = s.vel.x; child.vel.y = s.vel.y; child.vel.z = s.vel.z;
      // Inherit some of parent's orientation
      child.orientation.yaw = angle;
      child.dir = angle;
      s.spawnedFighters = (s.spawnedFighters ?? 0) + 1;
      s.fighterSpawnCdLeft = cfg.fighterSpawnCooldown ?? CarrierSpawnConfig.fighterSpawn.baseCooldown;
    }
  }
}

export function simulateStep(state: GameState, dt: number) {
  // Ship AI logic - Always use AIController for unified behavior
  // Lazily create and reuse AIController instance
  const aiController = state.aiController ?? (state.aiController = new AIController(state));
  aiController.updateAllShips(dt);
  
  // Update spatial grid with current ship positions after AI movement
  updateSpatialGrid(state);
  
  // Turret firing for all ships
  for (const s of state.ships) {
    if (s.health <= 0) continue;
    fireTurrets(state, s, dt);
  }
  
  // Bullets
  updateBullets(state, dt);
  // Deaths/XP
  processDeathsAndXP(state);
  handleLevelUps(state);
  // Carriers spawning
  carrierSpawnLogic(state, dt);

  // Periodic boundary cleanup (teleport or prune entities outside bounds)
  const cleanupEnabled = state.behaviorConfig?.globalSettings.enableBoundaryCleanup;
  const cleanupInterval = state.behaviorConfig?.globalSettings.boundaryCleanupIntervalTicks ?? 600;
  if (cleanupEnabled) {
    // Run once every cleanupInterval ticks
    if ((state.tick % cleanupInterval) === 0) {
      runBoundaryCleanup(state);
    }
  }
}

function runBoundaryCleanup(state: GameState) {
  const bounds = state.simConfig.simBounds;
  const shipsOutside: Ship[] = [];
  for (const s of state.ships) {
    if (s.pos.x < 0 || s.pos.x > bounds.width || s.pos.y < 0 || s.pos.y > bounds.height || s.pos.z < 0 || s.pos.z > bounds.depth) {
      shipsOutside.push(s);
    }
  }

  // Teleport ships back to a team spawn center with small deterministic jitter
  for (const s of shipsOutside) {
    // Attempt to find team spawn center using FleetConfig spawning margin/width
    const margin = FleetConfig.spawning.margin;
    const spawnWidth = FleetConfig.spawning.spawnWidth;
    const teamCenterX = s.team === 'red' ? margin + Math.floor(spawnWidth / 2) : state.simConfig.simBounds.width - margin - Math.floor(spawnWidth / 2);
    const centerY = Math.floor(state.simConfig.simBounds.height / 2);
    const centerZ = Math.floor(state.simConfig.simBounds.depth / 2);
    // Deterministic jitter using state's RNG
    const jitter = 16; // small teleport jitter in units
    const jx = (state.rng.next() - 0.5) * jitter * 2;
    const jy = (state.rng.next() - 0.5) * jitter * 2;
    const jz = (state.rng.next() - 0.5) * jitter * 2;
    s.pos.x = clamp(teamCenterX + jx, 0, state.simConfig.simBounds.width);
    s.pos.y = clamp(centerY + jy, 0, state.simConfig.simBounds.height);
    s.pos.z = clamp(centerZ + jz, 0, state.simConfig.simBounds.depth);
    // Reset velocity to zero to avoid teleporting while moving out
    s.vel.x = 0; s.vel.y = 0; s.vel.z = 0;
    // Clear target to avoid immediate re-targeting of far-away entities
    s.targetId = null;
  }

  // Prune bullets out of bounds (set ttl=0)
  for (const b of state.bullets) {
    if (b.pos.x < 0 || b.pos.x > bounds.width || b.pos.y < 0 || b.pos.y > bounds.height || b.pos.z < 0 || b.pos.z > bounds.depth) {
      b.ttl = 0;
    }
  }
  // Remove dead bullets immediately
  state.bullets = state.bullets.filter(b => b.ttl > 0);
}

/**
 * Update spatial grid with current ship positions
 */
function updateSpatialGrid(state: GameState) {
  if (!state.spatialGrid || !state.behaviorConfig?.globalSettings.enableSpatialIndex) {
    return;
  }

  // Incrementally update positions and purge stale ids without a full rebuild
  const activeIds = new Set<number>();
  for (const ship of state.ships) {
    if (ship.health > 0) {
      activeIds.add(ship.id);
      state.spatialGrid.update(ship.id, ship.pos, 16, ship.team);
    }
  }
  // Remove any entities no longer present/active
  state.spatialGrid.gcExcept(activeIds);
}

import type { GameState } from '../types/index.js';
import { PhysicsConfig } from '../config/physicsConfig.js';
import * as logger from '../utils/logger.js';

// Rapier physics scaffold
// Uses @dimforge/rapier3d-compat. This file creates a simple world and exposes a step function
// for the simulation loop. Keep physics state in simulation-only code to preserve determinism.

export interface PhysicsStepper {
  initDone: boolean;
  world: any;
  step: (dt: number) => void;
  dispose: () => void;
  // Enhanced methods
  addShip: (ship: any) => any;
  removeShip: (shipId: number) => void;
  raycast: (origin: { x: number; y: number; z: number }, direction: { x: number; y: number; z: number }, maxDistance?: number) => any;
  sphereCast: (center: { x: number; y: number; z: number }, radius: number) => any[];
  applyForce: (shipId: number, force: { x: number; y: number; z: number }) => void;
  setGravity: (gravity: { x: number; y: number; z: number }) => void;
}

export async function createPhysicsStepper(state: GameState): Promise<PhysicsStepper> {
  // Dynamically import rapier to avoid loading WASM at module eval time.
   
  const Rapier = require('@dimforge/rapier3d-compat') as any;

  // Create the physics world with enhanced settings
  const gravity = { x: 0, y: 0, z: 0 }; // Space has no gravity
  const world = new Rapier.World(gravity);

  // Configure world settings
  world.timestep = PhysicsConfig.world.timestep;
  world.maxVelocityIterations = PhysicsConfig.world.maxVelocityIterations;
  world.maxPositionIterations = PhysicsConfig.world.maxPositionIterations;

  // Store rigid bodies by ship ID
  const rigidBodies = new Map<number, any>();
  const colliders = new Map<number, any>();

  function addShip(ship: any) {
    try {
      // Create rigid body descriptor based on ship class
      const rbDesc = Rapier.RigidBodyDesc.dynamic()
        .setTranslation(ship.pos.x, ship.pos.y, ship.pos.z)
        .setLinvel(ship.vel.x, ship.vel.y, ship.vel.z)
        .setAngvel(0, 0, 0) // No initial angular velocity
        .setGravityScale(0) // No gravity in space
        .setLinearDamping(PhysicsConfig.damping.linear) // Small damping to prevent infinite sliding
        .setAngularDamping(PhysicsConfig.damping.angular); // Angular damping for stability

      const rigidBody = world.createRigidBody(rbDesc);
      rigidBodies.set(ship.id, rigidBody);

      // Create collider based on ship class
      let colliderDesc;
      const colliderDims = PhysicsConfig.colliders[ship.class as keyof typeof PhysicsConfig.colliders];
      if (colliderDims) {
        colliderDesc = Rapier.ColliderDesc.cuboid(colliderDims.width, colliderDims.height, colliderDims.depth);
      } else {
        const defaultCollider = PhysicsConfig.world.defaultCollider;
        colliderDesc = Rapier.ColliderDesc.cuboid(defaultCollider.width, defaultCollider.height, defaultCollider.depth);
      }

      // Configure collider properties
      colliderDesc.setDensity(PhysicsConfig.properties.density);
      colliderDesc.setFriction(PhysicsConfig.properties.friction);
      colliderDesc.setRestitution(PhysicsConfig.properties.restitution);

      const collider = world.createCollider(colliderDesc, rigidBody);
      colliders.set(ship.id, collider);

      return rigidBody;
    } catch (_e) { void _e;logger.error('Failed to create physics body for ship:', _e);
      return null;
    }
  }

  function removeShip(shipId: number) {
    try {
      const collider = colliders.get(shipId);
      if (collider) {
        world.removeCollider(collider, true);
        colliders.delete(shipId);
      }

      const rigidBody = rigidBodies.get(shipId);
      if (rigidBody) {
        world.removeRigidBody(rigidBody);
        rigidBodies.delete(shipId);
      }
    } catch (_e) { void _e;logger.error('Failed to remove physics body:', _e);
    }
  }

  function raycast(origin: { x: number; y: number; z: number }, direction: { x: number; y: number; z: number }, maxDistance = PhysicsConfig.world.defaultRaycastDistance) {
    try {
      const ray = new Rapier.Ray(origin, direction);
      const hit = world.castRay(ray, maxDistance, true);

      if (hit) {
        return {
          hit: true,
          distance: hit.toi,
          point: ray.pointAt(hit.toi),
          collider: hit.collider,
          rigidBody: hit.collider.parent()
        };
      }

      return { hit: false };
    } catch (_e) { void _e;logger.error('Raycast failed:', _e);
      return { hit: false };
    }
  }

  function sphereCast(center: { x: number; y: number; z: number }, radius: number) {
    try {
      const shape = new Rapier.Ball(radius);
      const shapePos = center;
      const shapeRot = { x: 0, y: 0, z: 0, w: 1 }; // Identity quaternion

      const hit = world.castShape(shapePos, shapeRot, shape, 0, true);

      if (hit) {
        return [{
          hit: true,
          distance: hit.toi,
          point: hit.point,
          collider: hit.collider,
          rigidBody: hit.collider.parent()
        }];
      }

      return [];
    } catch (_e) { void _e;logger.error('Sphere cast failed:', _e);
      return [];
    }
  }

  function applyForce(shipId: number, force: { x: number; y: number; z: number }) {
    try {
      const rigidBody = rigidBodies.get(shipId);
      if (rigidBody) {
        rigidBody.addForce(force, true);
      }
    } catch (_e) { void _e;logger.error('Failed to apply force:', _e);
    }
  }

  function setGravity(newGravity: { x: number; y: number; z: number }) {
    try {
      world.gravity.x = newGravity.x;
      world.gravity.y = newGravity.y;
      world.gravity.z = newGravity.z;
    } catch (_e) { void _e;logger.error('Failed to set gravity:', _e);
    }
  }

  function step(dt: number) {
    try {
      // Update physics world
      world.timestep = dt;
      world.step();

      // Update ship positions and velocities from physics
      for (const [shipId, rigidBody] of rigidBodies) {
        const ship = state.ships.find(s => s.id === shipId);
        if (!ship) continue;

        try {
          const translation = rigidBody.translation();
          const linvel = rigidBody.linvel();

          ship.pos.x = translation.x;
          ship.pos.y = translation.y;
          ship.pos.z = translation.z;
          ship.vel.x = linvel.x;
          ship.vel.y = linvel.y;
          ship.vel.z = linvel.z;
        } catch (_e) { void _e;logger.error('Failed to update ship from physics:', _e);
        }
      }
    } catch (_e) { void _e;logger.error('Physics step failed:', _e);
    }
  }

  return {
    initDone: true,
    world,
    step,
    dispose() {
      try {
        // Clean up all colliders and rigid bodies
        for (const collider of colliders.values()) {
          world.removeCollider(collider, true);
        }
        for (const rigidBody of rigidBodies.values()) {
          world.removeRigidBody(rigidBody);
        }
        rigidBodies.clear();
        colliders.clear();
        world.free?.();
      } catch (_e) { void _e;logger.error('Failed to dispose physics world:', _e);
      }
    },
    addShip,
    removeShip,
    raycast,
    sphereCast,
    applyForce,
    setGravity
  };
}

import type { Vector3, EntityId, Team } from '../types/index.js';
import type { SpatialGrid, SpatialEntity } from '../utils/spatialGrid.js';

/**
 * Axis-aligned bounding box for spatial queries
 */
export interface AABB {
  min: Vector3;
  max: Vector3;
}

/**
 * Spatial query result with distance information
 */
export interface SpatialQueryResult {
  entity: SpatialEntity;
  distance: number;
  direction: Vector3; // Normalized direction from query point to entity
}

/**
 * Enhanced SpatialIndex adapter interface to decouple AI from a concrete grid.
 * Provides comprehensive spatial queries with performance optimization.
 */
export interface SpatialIndex {
  // Lifecycle
  init(config: { cellSize: number; worldAABB?: AABB }): void;
  clear(): void;
  dispose?(): void;

  // Registration and updates
  insert(entityId: EntityId, pos: Vector3, radius: number, team: Team): void;
  update(id: EntityId, pos: Vector3, radius: number, team: Team): void;
  remove(id: EntityId): void;
  gcExcept(activeIds: Set<EntityId>): void;

  // Basic queries (existing interface)
  queryRadius(center: Vector3, radius: number, out?: SpatialEntity[]): SpatialEntity[];
  forEachInRadius(
    center: Vector3,
    radius: number,
    fn: (dx: number, dy: number, dz: number, distSq: number, entity: SpatialEntity) => void
  ): void;
  queryKNearest(center: Vector3, k: number, team?: Team, excludeId?: EntityId): SpatialEntity[];
  querySector(center: Vector3, direction: Vector3, angleRadians: number, range: number, team?: Team, excludeId?: EntityId): SpatialEntity[];
  queryNeighbors(center: Vector3, radius: number, team: Team, excludeId?: EntityId): SpatialEntity[];
  forEachNeighborsDelta(
    center: Vector3,
    radius: number,
    team: Team,
    excludeId: EntityId | undefined,
    fn: (dx: number, dy: number, dz: number, distSq: number, entity: SpatialEntity) => void
  ): void;
  queryEnemies(center: Vector3, radius: number, team: Team): SpatialEntity[];
  queryBulletCollisions(bulletPos: Vector3, bulletRadius: number, maxShipRadius?: number): SpatialEntity[];

  // Enhanced queries
  queryAABB(aabb: AABB, layerMask?: number): EntityId[];
  queryRadiusWithDistance(center: Vector3, radius: number, layerMask?: number): SpatialQueryResult[];
  raycast(from: Vector3, to: Vector3, layerMask?: number): Array<{ entityId: EntityId; t: number; point: Vector3 }>;
  
  // Layer-based queries for performance optimization
  queryLayer(center: Vector3, radius: number, layer: number): SpatialEntity[];
  queryLayerMask(center: Vector3, radius: number, layerMask: number): SpatialEntity[];

  // Advanced spatial operations
  queryFrustum?(frustum: { planes: Array<{ normal: Vector3; distance: number }> }): EntityId[];
  queryPath?(from: Vector3, to: Vector3, width: number): SpatialEntity[];
  
  // Debug/metrics
  getStats(): { 
    items: number; 
    cells: number; 
    avgItemsPerCell: number;
    queriesPerFrame?: number;
    totalMemoryUsage?: number;
  };
  
  // Performance optimization
  enableBatching?(enable: boolean): void;
  flushBatch?(): void;
}

/**
 * Adapter implementation that delegates to the existing SpatialGrid.
 * Enhanced with additional query capabilities and performance tracking.
 */
export class SpatialGridAdapter implements SpatialIndex {
  private grid: SpatialGrid;
  private queryCount = 0;
  private frameQueryCount = 0;
  private lastFrameReset = 0;

  constructor(grid: SpatialGrid) {
    this.grid = grid;
  }

  init(config: { cellSize: number; worldAABB?: AABB }): void {
    // SpatialGrid is typically already initialized, but we could extend it
    // For now, this is a no-op as the existing grid handles its own initialization
  }

  clear(): void { 
    this.grid.clear(); 
  }

  dispose?(): void {
    // Clean up any resources if needed
    this.queryCount = 0;
    this.frameQueryCount = 0;
  }

  // Delegation to existing SpatialGrid methods
  insert(entityId: EntityId, pos: Vector3, radius: number, team: Team): void {
    this.grid.update(entityId, pos, radius, team);
  }

  update(id: EntityId, pos: Vector3, radius: number, team: Team): void { 
    this.grid.update(id, pos, radius, team); 
  }

  remove(id: EntityId): void { 
    this.grid.remove(id); 
  }

  gcExcept(activeIds: Set<EntityId>): void { 
    this.grid.gcExcept(activeIds); 
  }

  queryRadius(center: Vector3, radius: number, out?: SpatialEntity[]): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.queryRadius(center, radius, out); 
  }

  forEachInRadius(center: Vector3, radius: number, fn: (dx: number, dy: number, dz: number, distSq: number, entity: SpatialEntity) => void): void { 
    this.trackQuery();
    this.grid.forEachInRadius(center, radius, fn); 
  }

  queryKNearest(center: Vector3, k: number, team?: Team, excludeId?: EntityId): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.queryKNearest(center, k, team, excludeId); 
  }

  querySector(center: Vector3, direction: Vector3, angleRadians: number, range: number, team?: Team, excludeId?: EntityId): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.querySector(center, direction, angleRadians, range, team, excludeId); 
  }

  queryNeighbors(center: Vector3, radius: number, team: Team, excludeId?: EntityId): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.queryNeighbors(center, radius, team, excludeId); 
  }

  forEachNeighborsDelta(center: Vector3, radius: number, team: Team, excludeId: EntityId | undefined, fn: (dx: number, dy: number, dz: number, distSq: number, entity: SpatialEntity) => void): void { 
    this.trackQuery();
    this.grid.forEachNeighborsDelta(center, radius, team, excludeId, fn); 
  }

  queryEnemies(center: Vector3, radius: number, team: Team): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.queryEnemies(center, radius, team); 
  }

  queryBulletCollisions(bulletPos: Vector3, bulletRadius: number, maxShipRadius?: number): SpatialEntity[] { 
    this.trackQuery();
    return this.grid.queryBulletCollisions(bulletPos, bulletRadius, maxShipRadius); 
  }

  // Enhanced query implementations
  queryAABB(aabb: AABB, layerMask?: number): EntityId[] {
    this.trackQuery();
    const results: EntityId[] = [];
    
    // Calculate search radius as half the diagonal of the AABB
    const center = {
      x: (aabb.min.x + aabb.max.x) / 2,
      y: (aabb.min.y + aabb.max.y) / 2,
      z: (aabb.min.z + aabb.max.z) / 2,
    };
    
    // Use diagonal distance to ensure we capture all possible entities
    const dx = aabb.max.x - aabb.min.x;
    const dy = aabb.max.y - aabb.min.y;
    const dz = aabb.max.z - aabb.min.z;
    const searchRadius = Math.sqrt(dx*dx + dy*dy + dz*dz) / 2 + 50; // Add buffer for entity radius

    const entities = this.grid.queryRadius(center, searchRadius);
    for (const entity of entities) {
      // Test if entity's position (considering its radius) intersects with AABB
      const entityMin = {
        x: entity.pos.x - entity.radius,
        y: entity.pos.y - entity.radius,
        z: entity.pos.z - entity.radius
      };
      const entityMax = {
        x: entity.pos.x + entity.radius,
        y: entity.pos.y + entity.radius,
        z: entity.pos.z + entity.radius
      };
      
      // Check AABB vs AABB intersection
      if (entityMax.x >= aabb.min.x && entityMin.x <= aabb.max.x &&
          entityMax.y >= aabb.min.y && entityMin.y <= aabb.max.y &&
          entityMax.z >= aabb.min.z && entityMin.z <= aabb.max.z) {
        // Apply layer mask if provided
        if (layerMask === undefined || ((1 << (entity.team === 'red' ? 0 : 1)) & layerMask)) {
          results.push(entity.id);
        }
      }
    }
    return results;
  }

  queryRadiusWithDistance(center: Vector3, radius: number, layerMask?: number): SpatialQueryResult[] {
    this.trackQuery();
    const results: SpatialQueryResult[] = [];
    const entities = this.grid.queryRadius(center, radius);
    
    for (const entity of entities) {
      // Apply layer mask if provided
      if (layerMask !== undefined && !((1 << (entity.team === 'red' ? 0 : 1)) & layerMask)) {
        continue;
      }

      const dx = entity.pos.x - center.x;
      const dy = entity.pos.y - center.y;
      const dz = entity.pos.z - center.z;
      const distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
      
      if (distance <= radius) {
        const direction = distance > 0 ? 
          { x: dx / distance, y: dy / distance, z: dz / distance } :
          { x: 0, y: 0, z: 0 };
        
        results.push({ entity, distance, direction });
      }
    }
    
    return results.sort((a, b) => a.distance - b.distance);
  }

  raycast(from: Vector3, to: Vector3, layerMask?: number): Array<{ entityId: EntityId; t: number; point: Vector3 }> {
    this.trackQuery();
    const results: Array<{ entityId: EntityId; t: number; point: Vector3 }> = [];
    
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const dz = to.z - from.z;
    const rayLength = Math.sqrt(dx * dx + dy * dy + dz * dz);
    
    if (rayLength === 0) return results;
    
    const dirX = dx / rayLength;
    const dirY = dy / rayLength;
    const dirZ = dz / rayLength;
    
    // Query entities along the ray path with some padding
    const center = {
      x: (from.x + to.x) / 2,
      y: (from.y + to.y) / 2,
      z: (from.z + to.z) / 2,
    };
    const queryRadius = rayLength / 2 + 50; // Add padding for entity radii
    
    const entities = this.grid.queryRadius(center, queryRadius);
    
    for (const entity of entities) {
      // Apply layer mask if provided
      if (layerMask !== undefined && !((1 << (entity.team === 'red' ? 0 : 1)) & layerMask)) {
        continue;
      }

      // Simple sphere-ray intersection
      const sphereX = entity.pos.x - from.x;
      const sphereY = entity.pos.y - from.y;
      const sphereZ = entity.pos.z - from.z;
      
      const dot = sphereX * dirX + sphereY * dirY + sphereZ * dirZ;
      if (dot < 0 || dot > rayLength) continue; // Behind ray or beyond end
      
      const closestX = from.x + dirX * dot;
      const closestY = from.y + dirY * dot;
      const closestZ = from.z + dirZ * dot;
      
      const distX = entity.pos.x - closestX;
      const distY = entity.pos.y - closestY;
      const distZ = entity.pos.z - closestZ;
      const distSq = distX * distX + distY * distY + distZ * distZ;
      
      if (distSq <= entity.radius * entity.radius) {
        const t = dot / rayLength;
        results.push({
          entityId: entity.id,
          t,
          point: { x: closestX, y: closestY, z: closestZ }
        });
      }
    }
    
    return results.sort((a, b) => a.t - b.t);
  }

  queryLayer(center: Vector3, radius: number, layer: number): SpatialEntity[] {
    this.trackQuery();
    const entities = this.grid.queryRadius(center, radius);
    const teamLayer = layer === 0 ? 'red' : 'blue';
    return entities.filter(e => e.team === teamLayer);
  }

  queryLayerMask(center: Vector3, radius: number, layerMask: number): SpatialEntity[] {
    this.trackQuery();
    const entities = this.grid.queryRadius(center, radius);
    return entities.filter(e => {
      const entityLayer = e.team === 'red' ? 0 : 1;
      return (1 << entityLayer) & layerMask;
    });
  }

  getStats() {
    const currentTime = performance.now();
    if (currentTime - this.lastFrameReset > 1000) { // Reset every second
      this.frameQueryCount = 0;
      this.lastFrameReset = currentTime;
    }

    // Mock implementation since SpatialGrid doesn't expose internal stats
    const itemCount = 100; // Would need to be exposed by SpatialGrid
    const cellCount = 64; // Would need to be exposed by SpatialGrid
    
    return { 
      items: itemCount, 
      cells: cellCount, 
      avgItemsPerCell: itemCount / cellCount,
      queriesPerFrame: this.frameQueryCount,
      totalMemoryUsage: itemCount * 64, // Rough estimate
    };
  }

  private trackQuery(): void {
    this.queryCount++;
    this.frameQueryCount++;
  }
}

