        const posInRow = index - (row * (row + 1)) / 2;
        const rowWidth = (row + 1) * spacing;
        const yOffset = posInRow * spacing - rowWidth / 2;
        const xOffset = row * spacing * 0.5;
        
        return {
          x: basePos.x + (team === 'red' ? xOffset : -xOffset),
          y: basePos.y + yOffset,
          z: basePos.z
        };
      }
      default:
