  })();
  (window as any).debugSVG = {
    // Get SVG loader stats
    getStats: () => {
      const stats = svgLoader.getCacheStats();
      logger.debug('[SVG Debug] Cache stats:', stats);
      return stats;
    },

    // Manually reload all SVG assets
    reloadAll: async () => {
      logger.debug('[SVG Debug] Manually reloading all SVG assets...');
      try {
        await svgLoader.reloadAllAssets();
        logger.debug('[SVG Debug] All SVG assets reloaded successfully');
      } catch (_error) { void _error;logger.error('[SVG Debug] Failed to reload SVG assets:', _error);
      }
    },

    // Clear SVG cache
    clearCache: (assetUrl?: string) => {
      logger.debug('[SVG Debug] Clearing SVG cache...', assetUrl ? `for ${assetUrl}` : 'all assets');
      svgLoader.clearCache(assetUrl);
      logger.debug('[SVG Debug] SVG cache cleared');
    },

    // List cached assets
    listCached: () => {
      const assets = Array.from(svgLoader.getCacheStats().cachedAssets > 0 ? 'assets cached' : []);
      logger.debug('[SVG Debug] Cached SVG assets:', assets);
      return assets;
    }
  };

  logger.debug('[main.ts] SVG debugging functions available at window.debugSVG');
  logger.debug('[main.ts] Use debugSVG.getStats(), debugSVG.reloadAll(), debugSVG.clearCache(), debugSVG.listCached()');

  // Optionally preload common ship assets into the pool (config-driven)
  (async () => {
    try {
      const classes: string[] = ['fighter','corvette','frigate','destroyer','carrier'];
      for (const cls of classes) {
        const url = `/assets/models/ship-${cls}.gltf`;
        // Attempt to load; if not present, loader will fail silently
        try {
          const res = await loadGLTF(state, url);
          if (state.assetPool) {
            state.assetPool.set(`ship-${cls}-red`, res);
            state.assetPool.set(`ship-${cls}-blue`, res);
          }
        } catch (_e) { void _e;/* ignore missing assets */ }
      }
    } catch (_e) { void _e;/* ignore */ }
  })();

  // Try to run Rapier in a worker (simWorker). If that fails, fall back to in-thread physics stepper.
  (async () => {
    try {
      // Create a module worker for simWorker.ts
      const w = new Worker(new URL('./simWorker.ts', import.meta.url), { type: 'module' });
      let ready = false;
      let lastShipDataVersion = -1;
      
      w.addEventListener('message', (ev) => {
        const data = ev.data || {};
        const type = data.type;
        // init handshake
        if (type === 'init-physics-done') {
          ready = !!data.ok;
          return;
        }

        // step result: supports packed Float32Array buffer (transformsBuffer)
        if (type === 'step-physics-done') {
          // Prefer transferable typed-array buffer payload for low-overhead transfer
          const buf = data.transformsBuffer || (data.transforms && data.transforms.buffer) || null;
          if (buf) {
            try {
              const arr = new Float32Array(buf);
              // Each entry is [id, px, py, pz, vx, vy, vz]
              for (let i = 0; i < arr.length; i += 7) {
                const id = Math.floor(arr[i]);
                const ship = state.shipIndex?.get(id) ?? state.ships.find(s => s.id === id);
                if (!ship) continue;
                ship.pos.x = arr[i + 1]; ship.pos.y = arr[i + 2]; ship.pos.z = arr[i + 3];
                ship.vel.x = arr[i + 4]; ship.vel.y = arr[i + 5]; ship.vel.z = arr[i + 6];
              }
            } catch (_e) { void _e;// Fallback to older object-based transforms if parsing fails
              const transforms = data.transforms || [];
              for (const transform of transforms) {
                const ship = state.shipIndex?.get(transform.shipId) ?? state.ships.find(s => s.id === transform.shipId);
                if (ship) {
                  ship.pos.x = transform.pos.x; ship.pos.y = transform.pos.y; ship.pos.z = transform.pos.z;
                  ship.vel.x = transform.vel.x; ship.vel.y = transform.vel.y; ship.vel.z = transform.vel.z;
                }
              }
            }
          } else if (data.transforms) {
            // Legacy: array of objects
            for (const transform of data.transforms) {
              const ship = state.shipIndex?.get(transform.shipId) ?? state.ships.find(s => s.id === transform.shipId);
              if (ship) {
                ship.pos.x = transform.pos.x; ship.pos.y = transform.pos.y; ship.pos.z = transform.pos.z;
                ship.vel.x = transform.vel.x; ship.vel.y = transform.vel.y; ship.vel.z = transform.vel.z;
              }
            }
          }
          return;
        }
      });
      
      w.postMessage({ type: 'init-physics' });

      // Expose a small shim for callers that expects physicsStepper API
      (state as any).physicsStepper = {
        initDone: false,
        step(dt: number) {
          try { 
            // Send current ship data to worker only if it has changed
            const currentVersion = state.shipDataVersion;
            if (currentVersion !== lastShipDataVersion) {
              const shipData = state.ships.map(ship => ({
                id: ship.id,
                pos: { ...ship.pos },
                vel: { ...ship.vel }
              }));
              w.postMessage({ type: 'update-ships', payload: { ships: shipData } });
              lastShipDataVersion = currentVersion;
            }
            
            // Step physics
            w.postMessage({ type: 'step-physics', payload: { dt } }); 
          } catch (_e) { void _e;/* ignore */ }
        },
        dispose() { try { w.postMessage({ type: 'dispose-physics' }); } catch (_e) { void _e;/* ignore */ } },
      };

      // Wait a short time for readiness, then mark initDone if ready
      setTimeout(() => { if ((state as any).physicsStepper) (state as any).physicsStepper.initDone = ready; }, 200);
    } catch (_e) { void _e;// Fallback to in-process physics stepper
      try {
        const ps = await createPhysicsStepper(state as any);
        (state as any).physicsStepper = ps;
      } catch (ee) { void ee;/* ignore */ }
    }
  })();
  // Seeded initial fleets
  spawnFleet(state, 'red', FleetConfig.spawning.defaultFleetSize);
  spawnFleet(state, 'blue', FleetConfig.spawning.defaultFleetSize);
  reFormFleets(state);
  const renderer = createThreeRenderer(state, ui.canvas);
  state.renderer = renderer;
  wireControls(state, ui);
  setupCameraControls(state, ui.canvas);
  startLoops(state, ui);
}

function wireControls(state: GameState, ui: UIElements) {
  function updateSpeedLabel() { ui.speed.textContent = `Speed: ${state.speedMultiplier}×`; }
  function updateRunLabel() { ui.startPause.textContent = state.running ? '⏸ Pause' : '▶ Start'; }
  function updateScores() { ui.redScore.textContent = `Red ${state.score.red}`; ui.blueScore.textContent = `Blue ${state.score.blue}`; }

  ui.startPause.onclick = () => { state.running = !state.running; updateRunLabel(); };
  ui.reset.onclick = () => { resetState(state); spawnFleet(state,'red', FleetConfig.spawning.defaultFleetSize); spawnFleet(state,'blue', FleetConfig.spawning.defaultFleetSize); reFormFleets(state); updateScores(); };
  ui.addRed.onclick = () => { spawnShip(state, 'red', randomClass(state)); };
  ui.addBlue.onclick = () => { spawnShip(state, 'blue', randomClass(state)); };
  ui.toggleTrails.onclick = () => { RendererConfig.visual.enableTrails = !RendererConfig.visual.enableTrails; ui.toggleTrails.textContent = `☄ Trails: ${RendererConfig.visual.enableTrails ? 'On' : 'Off'}`; };
  ui.speed.onclick = () => {
    const seq = [0.5, 1, 2, 4] as const; const i = seq.indexOf(state.speedMultiplier as any);
    const next = seq[(i + 1) % seq.length]; state.speedMultiplier = next; updateSpeedLabel();
  };
  ui.seedBtn.onclick = () => { const s = `SEED-${Date.now()}`; resetState(state, s); spawnFleet(state,'red', FleetConfig.spawning.defaultFleetSize); spawnFleet(state,'blue', FleetConfig.spawning.defaultFleetSize); reFormFleets(state); updateScores(); };
  ui.formationBtn.onclick = () => {
    // Clear existing ships
    state.ships = [];
    state.bullets = [];
    // Spawn randomized fleets
    const fleetSize = FleetConfig.spawning.defaultFleetSize;
    for (let i = 0; i < fleetSize; i++) {
      const redClass = randomClass(state);
      const blueClass = randomClass(state);
      spawnShip(state, 'red', redClass);
      spawnShip(state, 'blue', blueClass);
    }
    updateScores();
  };

  updateSpeedLabel(); updateRunLabel(); updateScores();
}

function resetToCinematicView(state: GameState) {
  if (!state.renderer || state.ships.length === 0) return;

  // Calculate center of mass of all alive ships
  let centerX = 0, centerY = 0, centerZ = 0;
  let shipCount = 0;

  for (const ship of state.ships) {
    if (ship.health > 0) { // Only count alive ships
      centerX += ship.pos.x;
      centerY += ship.pos.y;
      centerZ += ship.pos.z;
      shipCount++;
    }
  }

  if (shipCount === 0) return;

  centerX /= shipCount;
  centerY /= shipCount;
  centerZ /= shipCount;

  // Calculate the spread (bounding box) of ships to determine optimal zoom
  let minX = Infinity, maxX = -Infinity;
  let minY = Infinity, maxY = -Infinity;
  let minZ = Infinity, maxZ = -Infinity;

  for (const ship of state.ships) {
    if (ship.health > 0) {
      minX = Math.min(minX, ship.pos.x);
      maxX = Math.max(maxX, ship.pos.x);
      minY = Math.min(minY, ship.pos.y);
      maxY = Math.max(maxY, ship.pos.y);
      minZ = Math.min(minZ, ship.pos.z);
      maxZ = Math.max(maxZ, ship.pos.z);
    }
  }

  // Calculate dimensions of the ship cluster
  const spreadX = maxX - minX;
  const spreadY = maxY - minY;
  const spreadZ = maxZ - minZ;
  const maxSpread = Math.max(spreadX, spreadY, spreadZ);

  // Set camera target to center of mass
  state.renderer.cameraTarget.x = centerX;
  state.renderer.cameraTarget.y = centerY;
  state.renderer.cameraTarget.z = centerZ;

  // Calculate optimal distance based on spread and camera FOV
  const fovRadians = (RendererConfig.camera.fov * Math.PI) / 180;
  const optimalDistance = (maxSpread / 2) / Math.tan(fovRadians / 2) * CameraConfig.resetToCinematic.fovMultiplier; // 1.5x for comfortable viewing

  // Set distance with some minimum/maximum bounds
  state.renderer.cameraDistance = Math.max(CameraConfig.cinematic.minDistance, Math.min(CameraConfig.cinematic.maxDistance, optimalDistance));

  // Reset camera rotation to a good default viewing angle
  state.renderer.cameraRotation.x = CameraConfig.resetToCinematic.cameraRotation.x; // Slight downward tilt
  state.renderer.cameraRotation.y = CameraConfig.resetToCinematic.cameraRotation.y; // Face the action
  state.renderer.cameraRotation.z = CameraConfig.resetToCinematic.cameraRotation.z;
}

function updateCinematicCamera(state: GameState, dt: number) {
  if (!state.renderer || state.ships.length === 0) return;

  // Separate ships by team
  const redShips = state.ships.filter(s => s.team === 'red' && s.health > 0);
  const blueShips = state.ships.filter(s => s.team === 'blue' && s.health > 0);

  if (redShips.length === 0 || blueShips.length === 0) return;

  // Calculate center of each fleet
  let redCenterX = 0, redCenterY = 0, redCenterZ = 0;
  let blueCenterX = 0, blueCenterY = 0, blueCenterZ = 0;

  for (const ship of redShips) {
    redCenterX += ship.pos.x;
    redCenterY += ship.pos.y;
    redCenterZ += ship.pos.z;
  }
  redCenterX /= redShips.length;
  redCenterY /= redShips.length;
  redCenterZ /= redShips.length;

  for (const ship of blueShips) {
    blueCenterX += ship.pos.x;
    blueCenterY += ship.pos.y;
    blueCenterZ += ship.pos.z;
  }
  blueCenterX /= blueShips.length;
  blueCenterY /= blueShips.length;
  blueCenterZ /= blueShips.length;

  // Calculate the midpoint between both fleets
  const centerX = (redCenterX + blueCenterX) / 2;
  const centerY = (redCenterY + blueCenterY) / 2;
  const centerZ = (redCenterZ + blueCenterZ) / 2;

  // Calculate distance between fleets for optimal zoom
  const fleetDistance = Math.sqrt(
    Math.pow(redCenterX - blueCenterX, 2) +
    Math.pow(redCenterY - blueCenterY, 2) +
    Math.pow(redCenterZ - blueCenterZ, 2)
  );

  // Calculate optimal camera distance (show both fleets with some margin)
  const fovRadians = (RendererConfig.camera.fov * Math.PI) / 180;
  const optimalDistance = Math.max(fleetDistance * CameraConfig.cinematic.fleetDistanceMultiplier, CameraConfig.cinematic.minDistance); // Minimum distance of 500

  // Smoothly interpolate camera target
  const lerpFactor = Math.min(dt * CameraConfig.cinematic.lerpFactor, 1); // Smooth following with 2 seconds lerp time
  state.renderer.cameraTarget.x += (centerX - state.renderer.cameraTarget.x) * lerpFactor;
  state.renderer.cameraTarget.y += (centerY - state.renderer.cameraTarget.y) * lerpFactor;
  state.renderer.cameraTarget.z += (centerZ - state.renderer.cameraTarget.z) * lerpFactor;

  // Smoothly interpolate camera distance
  const distanceLerpFactor = Math.min(dt * CameraConfig.cinematic.distanceLerpFactor, 1); // Slower distance adjustment
  state.renderer.cameraDistance += (optimalDistance - state.renderer.cameraDistance) * distanceLerpFactor;

  // Clamp distance
  state.renderer.cameraDistance = Math.max(CameraConfig.cinematic.minDistance, Math.min(CameraConfig.cinematic.maxDistance, state.renderer.cameraDistance));
}

function setupCameraControls(state: GameState, canvas: HTMLCanvasElement) {
  if (!state.renderer) return;

  let isMouseDown = false;
  let lastMouseX = 0;
  let lastMouseY = 0;
  let isCinematicMode = false;

  // Mouse controls for rotation (click and drag)
  canvas.addEventListener('mousedown', (e) => {
    isMouseDown = true;
    lastMouseX = e.clientX;
    lastMouseY = e.clientY;
  });

  canvas.addEventListener('mouseup', () => {
    isMouseDown = false;
  });

  canvas.addEventListener('mousemove', (e) => {
    if (!isMouseDown || !state.renderer) return;

    const sensitivity = CameraConfig.controls.mouseSensitivity;
    const deltaX = (e.clientX - lastMouseX) * sensitivity;
    const deltaY = (e.clientY - lastMouseY) * sensitivity;

    // Update camera rotation
    state.renderer.cameraRotation.y += deltaX;
    state.renderer.cameraRotation.x += deltaY;

    // Clamp vertical rotation to prevent flipping
    state.renderer.cameraRotation.x = Math.max(-Math.PI/2, Math.min(Math.PI/2, state.renderer.cameraRotation.x));

    lastMouseX = e.clientX;
    lastMouseY = e.clientY;
  });

  // Mouse wheel for zoom (move camera forward/back)
  canvas.addEventListener('wheel', (e) => {
    if (!state.renderer) return;
    e.preventDefault();

    const zoomSpeed = CameraConfig.controls.zoomSpeed; // Fixed zoom speed
    const zoomDirection = e.deltaY > 0 ? 1 : -1; // Positive deltaY = zoom out (move back), negative = zoom in (move forward)

    // Calculate camera's forward vector
    const pitch = state.renderer.cameraRotation.x;
    const yaw = state.renderer.cameraRotation.y;
    const forwardX = Math.cos(yaw) * Math.cos(pitch);
    const forwardY = Math.sin(pitch);
    const forwardZ = Math.sin(yaw) * Math.cos(pitch);

    // Move camera and target together along forward vector
    const moveDistance = zoomSpeed * zoomDirection;
    state.renderer.cameraTarget.x += forwardX * moveDistance;
    state.renderer.cameraTarget.y += forwardY * moveDistance;
    state.renderer.cameraTarget.z += forwardZ * moveDistance;
  });

  // Keyboard controls for movement
  const keys: { [key: string]: boolean } = {};
  document.addEventListener('keydown', (e) => {
    keys[e.code] = true;

    // Cinematic camera with 'C' key
    if (e.code === 'KeyC' && state.renderer) {
      e.preventDefault();
      isCinematicMode = true;
      resetToCinematicView(state); // Initial setup
      logger.info('🎬 Cinematic camera mode activated - following both fleets');
    }
  });

  document.addEventListener('keyup', (e) => {
    keys[e.code] = false;
  });

  // Update camera position based on WASD keys
  function updateCameraMovement(dt: number) {
    if (!state.renderer) return;

    const moveSpeed = CameraConfig.controls.moveSpeed * dt;
    const moveVector = { x: 0, y: 0, z: 0 };

    if (keys['KeyW']) moveVector.z -= moveSpeed; // Forward
    if (keys['KeyS']) moveVector.z += moveSpeed; // Backward
    if (keys['KeyA']) moveVector.x += moveSpeed; // Left
    if (keys['KeyD']) moveVector.x -= moveSpeed; // Right
    if (keys['ShiftLeft']) moveVector.y -= moveSpeed; // Down
    if (keys['Space']) moveVector.y += moveSpeed; // Up

    // Check if any movement keys are pressed to exit cinematic mode
    const hasMovementInput = keys['KeyW'] || keys['KeyS'] || keys['KeyA'] || keys['KeyD'] || keys['ShiftLeft'] || keys['Space'];
    if (hasMovementInput && isCinematicMode) {
      isCinematicMode = false;
      logger.info('🎮 Manual camera control activated - cinematic mode disabled');
    }

    // If cinematic mode is active and no manual input, update cinematic camera
    if (isCinematicMode && !hasMovementInput) {
      updateCinematicCamera(state, dt);
      return; // Skip manual movement when in cinematic mode
    }

    // Calculate camera's local coordinate system
    const pitch = state.renderer.cameraRotation.x;
    const yaw = state.renderer.cameraRotation.y;

    // Forward vector (direction camera is facing)
    const forwardX = Math.cos(yaw) * Math.cos(pitch);
    const forwardY = Math.sin(pitch);
    const forwardZ = Math.sin(yaw) * Math.cos(pitch);

    // Right vector (perpendicular to forward in horizontal plane)
    const rightX = -Math.sin(yaw);
    const rightY = 0;
    const rightZ = Math.cos(yaw);

    // Up vector (perpendicular to both forward and right)
    const upX = -Math.sin(pitch) * Math.cos(yaw);
    const upY = Math.cos(pitch);
    const upZ = -Math.sin(pitch) * Math.sin(yaw);

    // Calculate movement in world space
    const worldMoveX = moveVector.x * rightX + moveVector.y * upX + moveVector.z * forwardX;
    const worldMoveY = moveVector.x * rightY + moveVector.y * upY + moveVector.z * forwardY;
    const worldMoveZ = moveVector.x * rightZ + moveVector.y * upZ + moveVector.z * forwardZ;

    // Move both camera target and position together to maintain relative orientation
    state.renderer.cameraTarget.x += worldMoveX;
    state.renderer.cameraTarget.y += worldMoveY;
    state.renderer.cameraTarget.z += worldMoveZ;
  }

  // Add camera movement to the render loop
  const originalRender = state.renderer.render;
  state.renderer.render = function(dt: number) {
    updateCameraMovement(dt);
    originalRender.call(state.renderer, dt);
  };
}

function startLoops(state: GameState, ui: UIElements) {
  const fixedDt = 1 / state.simConfig.tickRate;
  let last = performance.now();
  let acc = 0;
  let fpsAccum = 0, fpsFrames = 0, fpsTime = 0;

  function frame(now: number) {
    const dt = (now - last) / 1000; last = now;
    acc += dt;
    if (state.running) {
      // Fixed-step simulation with speed multiplier
      const maxSteps = 5;
      let steps = 0;
      while (acc >= fixedDt && steps < maxSteps) {
        simulateStep(state, fixedDt * state.speedMultiplier);
        try { state.physicsStepper?.step(fixedDt * state.speedMultiplier); } catch (_e) { void _e;/* ignore if missing */ }
        state.time += fixedDt * state.speedMultiplier; state.tick++;
        acc -= fixedDt; steps++;
      }
      // Auto-respawn if continuous
      if ((ui.continuous.checked)) {
        const redAlive = state.ships.some(s => s.team === 'red');
        const blueAlive = state.ships.some(s => s.team === 'blue');
        if (!redAlive) spawnFleet(state, 'red', FleetConfig.spawning.defaultFleetSize);
        if (!blueAlive) spawnFleet(state, 'blue', FleetConfig.spawning.defaultFleetSize);
      }
    }

    // Render
    state.renderer?.render(dt);

    // Stats
    fpsAccum += dt; fpsFrames++; fpsTime += dt;
    if (fpsAccum >= 0.5) {
      const fps = Math.round(fpsFrames / fpsAccum);
      ui.stats.textContent = `FPS ${fps} • Ships ${state.ships.length} • Bullets ${state.bullets.length} • Tick ${state.tick}`;
      // Update scoreboard periodically
      (document.getElementById('redScore') as HTMLDivElement).textContent = `Red ${state.score.red}`;
      (document.getElementById('blueScore') as HTMLDivElement).textContent = `Blue ${state.score.blue}`;
      fpsAccum = 0; fpsFrames = 0;
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
}

// Boot
// Initialize logger debug mode from global game config so devs can toggle verbosity
logger.setDebug(!!DefaultGameConfig.ui.showDebugInfo);

window.addEventListener('DOMContentLoaded', () => initGame());

import { gsap } from 'gsap';
import type { GameState, RendererHandles } from '../types/index.js';
import type { Ship } from '../types/index.js';

export interface AnimationManager {
  initDone: boolean;
  animateCameraTo: (position: { x: number; y: number; z: number }, duration?: number) => Promise<void>;
  animateShipSpawn: (ship: Ship, renderer: RendererHandles) => void;
  animateShipDestruction: (ship: Ship, renderer: RendererHandles) => Promise<void>;
  animateExplosion: (position: { x: number; y: number; z: number }, intensity?: number) => Promise<void>;
  shakeCamera: (intensity: number, duration?: number) => void;
  animateUINumber: (element: HTMLElement, from: number, to: number, duration?: number) => void;
  dispose: () => void;
}

export function createAnimationManager(state: GameState): AnimationManager {
  // GSAP timeline for managing complex animation sequences
  const masterTimeline = gsap.timeline();

  // Camera animation queue to prevent conflicts
  let cameraAnimationInProgress = false;

  function animateCameraTo(targetPosition: { x: number; y: number; z: number }, duration = 2.0): Promise<void> {
    return new Promise((resolve) => {
      if (cameraAnimationInProgress || !state.renderer) {
        resolve();
        return;
      }

      cameraAnimationInProgress = true;

      const startPosition = {
        x: state.renderer.cameraTarget.x,
        y: state.renderer.cameraTarget.y,
        z: state.renderer.cameraTarget.z
      };

      gsap.to(startPosition, {
        x: targetPosition.x,
        y: targetPosition.y,
        z: targetPosition.z,
        duration,
        ease: "power2.inOut",
        onUpdate: () => {
          state.renderer!.cameraTarget.x = startPosition.x;
          state.renderer!.cameraTarget.y = startPosition.y;
          state.renderer!.cameraTarget.z = startPosition.z;
        },
        onComplete: () => {
          cameraAnimationInProgress = false;
          resolve();
        }
      });
    });
  }

  function animateShipSpawn(ship: Ship, renderer: RendererHandles) {
    // Find the ship mesh
    const shipMeshes = (renderer as any).shipMeshes as Map<number, any>;
    const mesh = shipMeshes?.get(ship.id);

    if (!mesh) return;

    // Start small and grow
    gsap.fromTo(mesh.scale,
      { x: 0, y: 0, z: 0 },
      {
        x: 1, y: 1, z: 1,
        duration: 0.8,
        ease: "back.out(1.7)",
        onStart: () => {
          // Add a subtle glow effect
          if (mesh.material && mesh.material.emissive) {
            gsap.fromTo(mesh.material.emissive,
              { r: 0, g: 0, b: 0 },
              { r: 0.2, g: 0.2, b: 0.4, duration: 0.4, yoyo: true, repeat: 1 }
            );
          }
        }
      }
    );
  }

  function animateShipDestruction(ship: Ship, renderer: RendererHandles): Promise<void> {
    return new Promise((resolve) => {
      const shipMeshes = (renderer as any).shipMeshes as Map<number, any>;
      const mesh = shipMeshes?.get(ship.id);

      if (!mesh) {
        resolve();
        return;
      }

      // Create destruction sequence
      const timeline = gsap.timeline({
        onComplete: resolve
      });

      // Flash white
      timeline.to(mesh.material.emissive, {
        r: 1, g: 1, b: 1,
        duration: 0.1
      });

      // Scale up and rotate
      timeline.to(mesh, {
        scaleX: 1.5,
        scaleY: 1.5,
        scaleZ: 1.5,
        rotationX: Math.PI * 2,
        rotationY: Math.PI * 2,
        duration: 0.3,
        ease: "power2.in"
      }, "<");

      // Fade out and shrink
      timeline.to(mesh, {
        scaleX: 0,
        scaleY: 0,
        scaleZ: 0,
        opacity: 0,
        duration: 0.4,
        ease: "power2.out"
      });

      // Reset emissive
      timeline.to(mesh.material.emissive, {
        r: 0, g: 0, b: 0,
        duration: 0.1
      }, "<");
    });
  }

  function animateExplosion(position: { x: number; y: number; z: number }, intensity = 1.0): Promise<void> {
    return new Promise((resolve) => {
      // Create a temporary explosion sprite or use postprocessing effects
      const effectsManager = (state.renderer as any).effectsManager;
      if (effectsManager && effectsManager.addExplosionEffect) {
        effectsManager.addExplosionEffect(position, intensity);
      }

      // Camera shake
      shakeCamera(intensity * 0.5, 0.3);

      // Resolve after animation completes
      setTimeout(resolve, 500);
    });
  }

  function shakeCamera(intensity: number, duration = 0.5) {
    if (!state.renderer) return;

    const originalPosition = {
      x: state.renderer.cameraTarget.x,
      y: state.renderer.cameraTarget.y,
      z: state.renderer.cameraTarget.z
    };

    gsap.to({}, {
      duration,
      ease: "power2.out",
      onUpdate: function() {
        const progress = this.progress();
        const shake = (1 - progress) * intensity;

        state.renderer!.cameraTarget.x = originalPosition.x + (Math.random() - 0.5) * shake;
        state.renderer!.cameraTarget.y = originalPosition.y + (Math.random() - 0.5) * shake;
        state.renderer!.cameraTarget.z = originalPosition.z + (Math.random() - 0.5) * shake;
      },
      onComplete: () => {
        state.renderer!.cameraTarget.x = originalPosition.x;
        state.renderer!.cameraTarget.y = originalPosition.y;
        state.renderer!.cameraTarget.z = originalPosition.z;
      }
    });
  }

  function animateUINumber(element: HTMLElement, from: number, to: number, duration = 1.0) {
    const obj = { value: from };

    gsap.to(obj, {
      value: to,
      duration,
      ease: "power2.out",
      onUpdate: () => {
        element.textContent = Math.round(obj.value).toString();
      }
    });
  }

  return {
    initDone: true,
    animateCameraTo,
    animateShipSpawn,
    animateShipDestruction,
    animateExplosion,
    shakeCamera,
    animateUINumber,
    dispose: () => {
      masterTimeline.kill();
    }
  };
}

import * as THREE from 'three';
import { MeshBVH, acceleratedRaycast, computeBoundsTree, disposeBoundsTree } from 'three-mesh-bvh';
import type { GameState, Ship, Bullet } from '../types/index.js';

// Enable accelerated raycasting
THREE.Mesh.prototype.raycast = acceleratedRaycast;
THREE.BufferGeometry.prototype.computeBoundsTree = computeBoundsTree;
THREE.BufferGeometry.prototype.disposeBoundsTree = disposeBoundsTree;

export interface BVHManager {
  initDone: boolean;
  updateBVH: (ships: Ship[]) => void;
  raycast: (origin: THREE.Vector3, direction: THREE.Vector3, maxDistance?: number) => THREE.Intersection[];
  sphereCast: (center: THREE.Vector3, radius: number) => Ship[];
  dispose: () => void;
}

export function createBVHManager(state: GameState): BVHManager {
  // BVH for ships
  let shipBVH: MeshBVH | null = null;
  let shipGeometry: THREE.BufferGeometry | null = null;
  let shipMesh: THREE.Mesh | null = null;

  // Scene for BVH operations
  const bvhScene = new THREE.Scene();

  function updateBVH(ships: Ship[]) {
    // Clear previous BVH
    if (shipMesh) {
      bvhScene.remove(shipMesh);
      shipMesh.geometry.dispose();
      if (shipMesh.material instanceof THREE.Material) {
        shipMesh.material.dispose();
      }
    }

    if (ships.length === 0) {
      shipBVH = null;
      return;
    }

    // Create geometry for all ships
    const positions: number[] = [];
    const indices: number[] = [];
    const shipData: Ship[] = []; // Store ship references

    ships.forEach((ship, shipIndex) => {
      // Create a simple bounding box for each ship
      const halfWidth = 10; // Ship half-width
      const halfHeight = 5; // Ship half-height
      const halfDepth = 10; // Ship half-depth

      // Define 8 vertices of the bounding box
      const vertices = [
        // Bottom face
        ship.pos.x - halfWidth, ship.pos.y - halfHeight, ship.pos.z - halfDepth,
        ship.pos.x + halfWidth, ship.pos.y - halfHeight, ship.pos.z - halfDepth,
        ship.pos.x + halfWidth, ship.pos.y - halfHeight, ship.pos.z + halfDepth,
        ship.pos.x - halfWidth, ship.pos.y - halfHeight, ship.pos.z + halfDepth,
        // Top face
        ship.pos.x - halfWidth, ship.pos.y + halfHeight, ship.pos.z - halfDepth,
        ship.pos.x + halfWidth, ship.pos.y + halfHeight, ship.pos.z - halfDepth,
        ship.pos.x + halfWidth, ship.pos.y + halfHeight, ship.pos.z + halfDepth,
        ship.pos.x - halfWidth, ship.pos.y + halfHeight, ship.pos.z + halfDepth,
      ];

      const vertexOffset = positions.length / 3;

      // Add vertices
      positions.push(...vertices);

      // Define triangles for the bounding box
      const boxIndices = [
        // Bottom face
        0, 1, 2, 0, 2, 3,
        // Top face
        4, 5, 6, 4, 6, 7,
        // Front face
        0, 1, 5, 0, 5, 4,
        // Back face
        3, 2, 6, 3, 6, 7,
        // Left face
        0, 3, 7, 0, 7, 4,
        // Right face
        1, 2, 6, 1, 6, 5,
      ];

      // Add indices with offset
      indices.push(...boxIndices.map(i => i + vertexOffset));

      // Store ship reference (we'll use the ship index to map back)
      shipData[shipIndex] = ship;
    });

    // Create geometry
    shipGeometry = new THREE.BufferGeometry();
    shipGeometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    shipGeometry.setIndex(indices);

    // Compute BVH
    shipGeometry.computeBoundsTree();

    // Create mesh
    const material = new THREE.MeshBasicMaterial({ visible: false }); // Invisible helper mesh
    shipMesh = new THREE.Mesh(shipGeometry, material);
    bvhScene.add(shipMesh);

    // Store BVH reference
    shipBVH = (shipGeometry as any).boundsTree;
  }

  function raycast(origin: THREE.Vector3, direction: THREE.Vector3, maxDistance = 1000): THREE.Intersection[] {
    if (!shipBVH || !shipMesh) return [];

    const raycaster = new THREE.Raycaster(origin, direction.normalize(), 0, maxDistance);

    // Perform raycast against BVH
    const intersections: THREE.Intersection[] = [];
    raycaster.intersectObject(shipMesh, false, intersections);

    return intersections;
  }

  function sphereCast(center: THREE.Vector3, radius: number): Ship[] {
    if (!shipBVH || !shipMesh) return [];

    // For sphere casting, we'll use a simple distance check against all ships
    // In a more advanced implementation, you could use BVH for sphere queries
    const hits: Ship[] = [];

    state.ships.forEach(ship => {
      const distance = Math.sqrt(
        Math.pow(ship.pos.x - center.x, 2) +
        Math.pow(ship.pos.y - center.y, 2) +
        Math.pow(ship.pos.z - center.z, 2)
      );

      if (distance <= radius) {
        hits.push(ship);
      }
    });

    return hits;
  }

  return {
    initDone: true,
    updateBVH,
    raycast,
    sphereCast,
    dispose: () => {
      if (shipMesh) {
        bvhScene.remove(shipMesh);
        shipMesh.geometry.dispose();
        if (shipMesh.material instanceof THREE.Material) {
          shipMesh.material.dispose();
        }
      }
      shipBVH = null;
      shipGeometry = null;
      shipMesh = null;
    }
  };
}

import * as THREE from 'three';
import type { GameState } from '../types/index.js';
import { RendererConfig } from '../config/rendererConfig.js';

/**
 * Camera management and controls
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface CameraState {
  camera: THREE.PerspectiveCamera;
  rotation: { x: number; y: number; z: number };
  target: { x: number; y: number; z: number };
  distance: number;
}

export interface CameraManager {
  setupCamera(state: GameState): CameraState;
  updateCameraPosition(cameraState: CameraState): void;
  handleResize(cameraState: CameraState, width: number, height: number): void;
  setCameraDistance(cameraState: CameraState, distance: number): void;
  getCameraDistance(cameraState: CameraState): number;
  disposeCamera(cameraState: CameraState): void;
}

/**
 * Creates and configures the camera
 */
export function setupCamera(state: GameState): CameraState {
  const camera = new THREE.PerspectiveCamera(
    RendererConfig.camera.fov,
    1, // Will be updated on resize
    RendererConfig.camera.near,
    RendererConfig.camera.far
  );

  const rotation = {
    x: RendererConfig.camera.rotation.pitch,
    y: RendererConfig.camera.rotation.yaw,
    z: RendererConfig.camera.rotation.roll
  };

  const target = {
    x: state.simConfig.simBounds.width / 2,
    y: state.simConfig.simBounds.height / 2,
    z: state.simConfig.simBounds.depth / 2
  };

  const distance = RendererConfig.camera.cameraZ;

  const cameraState: CameraState = {
    camera,
    rotation,
    target,
    distance
  };

  // Set initial camera position
  updateCameraPosition(cameraState);

  return cameraState;
}

/**
 * Updates camera position based on spherical coordinates
 */
export function updateCameraPosition(cameraState: CameraState): void {
  const { camera, rotation, target, distance } = cameraState;

  const x = target.x + distance * Math.cos(rotation.y) * Math.cos(rotation.x);
  const y = target.y + distance * Math.sin(rotation.x);
  const z = target.z + distance * Math.sin(rotation.y) * Math.cos(rotation.x);

  camera.position.set(x, y, z);
  camera.lookAt(target.x, target.y, target.z);
}

/**
 * Handles window resize and updates camera aspect ratio
 */
export function handleResize(cameraState: CameraState, width: number, height: number): void {
  const { camera } = cameraState;
  
  camera.aspect = width / height;
  camera.updateProjectionMatrix();
  
  // Update camera position after aspect ratio change
  updateCameraPosition(cameraState);
}

/**
 * Sets the camera distance and updates position
 */
export function setCameraDistance(cameraState: CameraState, distance: number): void {
  cameraState.distance = distance;
  updateCameraPosition(cameraState);
}

/**
 * Gets the current camera distance
 */
export function getCameraDistance(cameraState: CameraState): number {
  return cameraState.distance;
}

/**
 * Updates camera rotation and position
 */
export function setCameraRotation(cameraState: CameraState, rotation: { x?: number; y?: number; z?: number }): void {
  if (rotation.x !== undefined) cameraState.rotation.x = rotation.x;
  if (rotation.y !== undefined) cameraState.rotation.y = rotation.y;
  if (rotation.z !== undefined) cameraState.rotation.z = rotation.z;
  updateCameraPosition(cameraState);
}

/**
 * Updates camera target and position
 */
export function setCameraTarget(cameraState: CameraState, target: { x?: number; y?: number; z?: number }): void {
  if (target.x !== undefined) cameraState.target.x = target.x;
  if (target.y !== undefined) cameraState.target.y = target.y;
  if (target.z !== undefined) cameraState.target.z = target.z;
  updateCameraPosition(cameraState);
}

/**
 * Gets camera basis vectors for billboard rendering
 */
export function getCameraBasisVectors(cameraState: CameraState): { right: THREE.Vector3; up: THREE.Vector3 } {
  const { camera } = cameraState;
  
  const camRight = new THREE.Vector3();
  const camUp = new THREE.Vector3();
  
  // Get camera forward direction
  camera.getWorldDirection(camRight); // This gets forward, we'll compute right from it
  
  // Calculate camera right vector: cross(up, forward)
  const worldUp = new THREE.Vector3(0, 1, 0);
  camRight.crossVectors(camera.up, camera.getWorldDirection(new THREE.Vector3())).normalize();
  camUp.copy(camera.up).normalize();
  
  return { right: camRight, up: camUp };
}

/**
 * Gets the camera matrix for billboard calculations
 */
export function getCameraMatrix(cameraState: CameraState): THREE.Matrix4 {
  return new THREE.Matrix4().extractRotation(cameraState.camera.matrixWorld);
}

/**
 * Disposes camera resources (minimal cleanup needed)
 */
export function disposeCamera(cameraState: CameraState): void {
  // Cameras don't have resources that need explicit disposal
  // This function exists for completeness and future extensibility
}

/**
 * Default camera manager implementation
 */
export const cameraManager: CameraManager = {
  setupCamera,
  updateCameraPosition,
  handleResize,
  setCameraDistance,
  getCameraDistance,
  disposeCamera
};

/**
 * Utility functions for camera calculations
 */
export const CameraUtils = {
  updateCameraPosition,
  setCameraRotation,
  setCameraTarget,
  getCameraBasisVectors,
  getCameraMatrix
};

import * as THREE from 'three';
import type { Ship } from '../../types/index.js';
import { RendererConfig } from '../../config/rendererConfig.js';
import { ShipVisualConfig } from '../../config/shipVisualConfig.js';
import { shieldVertexShader, createShieldFragmentShader } from './shieldShaders.js';

/**
 * Shield effects manager
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface ShieldEffectState {
  recentShieldHits: Map<number, { dir: THREE.Vector3; time: number; strength: number; }[]>;
}

export interface ShieldEffect {
  createShieldEffect(ship: Ship, state: ShieldEffectState): THREE.Object3D;
  updateShieldEffect(ship: Ship, shieldGroup: THREE.Object3D, currentTime: number, state: ShieldEffectState): void;
  disposeShieldEffect(shieldGroup: THREE.Object3D): void;
}

/**
 * Creates the shield effect state
 */
export function createShieldEffectState(): ShieldEffectState {
  return {
    recentShieldHits: new Map<number, { dir: THREE.Vector3; time: number; strength: number; }[]>()
  };
}

/**
 * Creates a shield effect for a ship
 */
export function createShieldEffect(ship: Ship, state: ShieldEffectState): THREE.Object3D {
  const config = RendererConfig.shield;
  const shieldGroup = new THREE.Group();

  // Spherical shield bubble with rim lighting and directional hit arc
  const geom = new THREE.SphereGeometry( 
    (ShipVisualConfig.ships[ship.class]?.collisionRadius ?? 16) * 1.1,
    24, 24
  );
  const teamColor = new THREE.Color(ship.team === 'red' ? config.colors.red : config.colors.blue);

  const HIT_MAX = Math.max(1, Math.floor(RendererConfig.shield.hexGrid.hitMax));
  const material = new THREE.ShaderMaterial({
    uniforms: {
      uColor: { value: teamColor },
      uTime: { value: 0.0 },
      uOpacity: { value: config.opacity.base },
      // Hex grid params
      uHexDensity: { value: config.hexGrid.density },
      uEdgeWidth: { value: config.hexGrid.edgeWidth },
      // Hit arc (directional)
      uHitDir: { value: new THREE.Vector3(0, 0, 1) },
      uHitStrength: { value: 0.0 },
      // Hex hit highlighting
      uHitCount: { value: 0 },
      uHitDirs: { value: Array.from({ length: HIT_MAX }, () => new THREE.Vector3(0,0,1)) },
      uHitTimes: { value: new Float32Array(HIT_MAX).fill(-1000) },
      uHitStrengths: { value: new Float32Array(HIT_MAX).fill(0) },
      uHitWindow: { value: config.hexGrid.hitWindow },
      uHexSplashRadius: { value: config.hexGrid.splashRadius },
      // Ripple settings
      uRippleAmplitude: { value: config.ripple.amplitude },
      uRippleSpeed: { value: config.ripple.speed },
      uRippleFalloff: { value: config.ripple.falloff },
      // Arc params
      uArcAlignStart: { value: config.arc.alignStart },
      uArcAlignEnd: { value: config.arc.alignEnd },
      uArcAlphaScale: { value: config.arc.alphaScale },
      uArcColorScale: { value: config.arc.colorScale },
      // Damage scaling
      uDamageNormalizeBy: { value: RendererConfig.shield.damage.normalizeBy },
      uDamageMinScale: { value: RendererConfig.shield.damage.minScale },
      uDamageMaxScale: { value: RendererConfig.shield.damage.maxScale },
    },
    vertexShader: shieldVertexShader,
    fragmentShader: createShieldFragmentShader(HIT_MAX),
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
  });

  const shieldMesh = new THREE.Mesh(geom, material);
  shieldGroup.add(shieldMesh);

  // Store the mesh reference for updates
  (shieldGroup as any).shieldMesh = shieldMesh;

  return shieldGroup;
}

/**
 * Updates the shield effect based on ship status and hits
 */
export function updateShieldEffect(
  ship: Ship, 
  shieldGroup: THREE.Object3D, 
  currentTime: number, 
  state: ShieldEffectState
): void {
  const config = RendererConfig.shield;
  const shieldMesh = (shieldGroup as any).shieldMesh as THREE.Mesh;
  const mat = shieldMesh.material as THREE.ShaderMaterial;

  // Position the shield around the ship (3D)
  shieldGroup.position.set(ship.pos.x, ship.pos.y, ship.pos.z);

  // Scale based on ship class
  const scale = ShipVisualConfig.ships[ship.class]?.scale ?? RendererConfig.defaultScale;
  shieldGroup.scale.setScalar(scale);

  // Update uniforms
  mat.uniforms.uTime.value = currentTime;
  const shieldPercent = ship.maxShield > 0 ? ship.shield / ship.maxShield : 0;
  mat.uniforms.uOpacity.value = config.opacity.base * shieldPercent + config.opacity.min * (1 - shieldPercent);

  // Handle recent hit tracking and visual effects
  const lastHitTime = ship.lastShieldHitTime || 0;
  const hitWindow = RendererConfig.shield.hexGrid.hitWindow; // seconds
  let timeDecay = 0.0;
  
  if (currentTime - lastHitTime < hitWindow) {
    timeDecay = 1.0 - (currentTime - lastHitTime) / hitWindow;
    // Push into recent hits buffer for hex highlighting (avoid duplicates per hit)
    const list = state.recentShieldHits.get(ship.id) ?? [];
    const d = ship.lastShieldHitDir || { x: 0, y: 0, z: 1 };
    const dmg = Math.max(0, ship.lastShieldHitStrength ?? 0);
    
    // Only push once per unique hit time
    if (!list.find(h => Math.abs(h.time - lastHitTime) < 0.01)) {
      const HIT_MAX = Math.max(1, Math.floor(RendererConfig.shield.hexGrid.hitMax));
      list.push({ dir: new THREE.Vector3(d.x, d.y, d.z), time: lastHitTime, strength: dmg });
      // Keep only recent hits
      const pruned = list.filter(h => currentTime - h.time <= hitWindow);
      // Keep only the most recent HIT_MAX hits
      while (pruned.length > HIT_MAX) pruned.shift();
      state.recentShieldHits.set(ship.id, pruned);
    }
  }

  // Update damage visualization
  const dmgNorm = RendererConfig.shield.damage.normalizeBy;
  const dmgMin = RendererConfig.shield.damage.minScale;
  const dmgMax = RendererConfig.shield.damage.maxScale;
  const dmgScale = Math.min(dmgMax, Math.max(0.0, (ship.lastShieldHitStrength ?? 0) / dmgNorm));
  const dmgScaleClamped = Math.max(dmgMin, dmgScale);
  mat.uniforms.uHitStrength.value = timeDecay * dmgScaleClamped;
  const dir = ship.lastShieldHitDir || { x: 0, y: 0, z: 1 };
  (mat.uniforms.uHitDir.value as THREE.Vector3).set(dir.x, dir.y, dir.z).normalize();

  // Update array uniforms for hex highlights
  const list = state.recentShieldHits.get(ship.id) ?? [];
  const HIT_MAX = Math.max(1, Math.floor(RendererConfig.shield.hexGrid.hitMax));
  const maxN = Math.min(HIT_MAX, list.length);
  mat.uniforms.uHitCount.value = maxN;
  const uDirs = (mat.uniforms.uHitDirs.value as THREE.Vector3[]);
  const uTimes = (mat.uniforms.uHitTimes.value as Float32Array);
  const uStrengths = (mat.uniforms.uHitStrengths.value as Float32Array);
  
  for (let i = 0; i < HIT_MAX; i++) {
    if (i < maxN) {
      uDirs[i].copy(list[i].dir).normalize();
      uTimes[i] = list[i].time;
      uStrengths[i] = list[i].strength;
    } else {
      uDirs[i].set(0, 0, 1);
      uTimes[i] = -1000; // Very old time
      uStrengths[i] = 0;
    }
  }
}

/**
 * Disposes shield effect resources
 */
export function disposeShieldEffect(shieldGroup: THREE.Object3D): void {
  const shieldMesh = (shieldGroup as any).shieldMesh as THREE.Mesh;
  if (shieldMesh) {
    if (shieldMesh.geometry) shieldMesh.geometry.dispose();
    if (shieldMesh.material) {
      if (Array.isArray(shieldMesh.material)) {
        shieldMesh.material.forEach(mat => mat.dispose());
      } else {
        shieldMesh.material.dispose();
      }
    }
  }
}

/**
 * Default shield effect implementation
 */
export const shieldEffect: ShieldEffect = {
  createShieldEffect,
  updateShieldEffect,
  disposeShieldEffect
};

import * as THREE from 'three';
import type { GameState, Ship, Bullet } from '../types/index.js';
import { RendererConfig } from '../config/rendererConfig.js';
import { ShipVisualConfig } from '../config/shipVisualConfig.js';
import { loadSVGAsset } from '../core/svgLoader.js';
import { defaultSVGConfig, getShipSVGUrl } from '../config/svgConfig.js';
import * as logger from '../utils/logger.js';
import { shipInstancer } from './shipInstancer.js';

/**
 * Mesh factory and pooling for ships, bullets, and UI elements
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface MeshFactoryState {
  billboardMaterials: Set<THREE.ShaderMaterial>;
  billboardMaterialPool: Map<string, THREE.ShaderMaterial>;
  GPU_BILLBOARD: boolean;
}

export interface MeshFactory {
  createShipMesh(ship: Ship, state: GameState, shipsGroup: THREE.Group, shipMeshes: Map<number, THREE.Object3D>): THREE.Object3D;
  createBulletMesh(bullet: Bullet): THREE.Object3D;
  createHealthBarMesh(ship: Ship, factoryState: MeshFactoryState): THREE.Object3D;
  updateHealthBarMesh(ship: Ship, barGroup: THREE.Object3D): void;
  getPooledBillboardMaterial(color: THREE.Color, alpha: number, factoryState: MeshFactoryState): THREE.ShaderMaterial;
  disposeMeshFactory(factoryState: MeshFactoryState): void;
}

/**
 * Creates the mesh factory state
 */
export function createMeshFactoryState(): MeshFactoryState {
  return {
    billboardMaterials: new Set<THREE.ShaderMaterial>(),
    billboardMaterialPool: new Map<string, THREE.ShaderMaterial>(),
    GPU_BILLBOARD: true // set to true to use shader-based billboarding for health bars
  };
}

/**
 * Creates a mesh for a ship with async SVG loading
 */
export function createShipMesh(
  ship: Ship, 
  state: GameState, 
  shipsGroup: THREE.Group, 
  shipMeshes: Map<number, THREE.Object3D>
): THREE.Object3D {
  const pool = (state as any).assetPool as Map<string, any> | undefined;
  const svgUrl = getShipSVGUrl(ship.class, defaultSVGConfig);

  const createTextured3DShip = (imageBitmap: ImageBitmap) => {
    const texture = new THREE.Texture(imageBitmap);
    texture.needsUpdate = true;
    texture.generateMipmaps = false;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;

    // Create materials - textured for main surfaces, team color for others
    const teamColor = ship.team === 'red' ? 0xff4444 : 0x4444ff;
    const texturedMaterial = new THREE.MeshBasicMaterial({
      map: texture,
      transparent: true,
      alphaTest: 0.05,
      side: THREE.DoubleSide
    });
    const teamMaterial = new THREE.MeshBasicMaterial({
      color: teamColor,
      transparent: true,
      opacity: 0.8,
      side: THREE.DoubleSide
    });

    // Create a group to hold the ship parts
    const shipGroup = new THREE.Group();

    const size = ShipVisualConfig.ships[ship.class]?.collisionRadius ?? RendererConfig.defaultCollisionRadius;

    // Main body - cylinder with SVG texture on the caps and team color on the sides
    const bodyGeometry = new THREE.CylinderGeometry(size * 0.3, size * 0.4, size * 0.8, 8);
    const bodyMaterials = [teamMaterial, texturedMaterial, texturedMaterial];
    const body = new THREE.Mesh(bodyGeometry, bodyMaterials);
    body.rotation.z = Math.PI / 2; // Orient along X-axis (nose direction)
    shipGroup.add(body);

    // Nose cone - pure team color
    const noseGeometry = new THREE.ConeGeometry(size * 0.3, size * 0.5, 8);
    const nose = new THREE.Mesh(noseGeometry, teamMaterial);
    nose.position.x = size * 0.65;
    nose.rotation.z = -Math.PI / 2; // Point along +X
    shipGroup.add(nose);

    // Wings/fins - textured planes on the sides for visibility from multiple angles
    const wingGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.4);
    const topWing = new THREE.Mesh(wingGeometry, texturedMaterial);
    topWing.position.y = size * 0.25;
    topWing.rotation.x = -Math.PI / 2;
    shipGroup.add(topWing);
    const bottomWing = new THREE.Mesh(wingGeometry, texturedMaterial);
    bottomWing.position.y = -size * 0.25;
    bottomWing.rotation.x = Math.PI / 2;
    shipGroup.add(bottomWing);

    // Side panels
    const sidePanelGeometry = new THREE.PlaneGeometry(size * 0.8, size * 0.3);
    const leftPanel = new THREE.Mesh(sidePanelGeometry, texturedMaterial);
    leftPanel.position.z = size * 0.2;
    leftPanel.rotation.y = Math.PI / 2;
    shipGroup.add(leftPanel);
    const rightPanel = new THREE.Mesh(sidePanelGeometry, texturedMaterial);
    rightPanel.position.z = -size * 0.2;
    rightPanel.rotation.y = -Math.PI / 2;
    shipGroup.add(rightPanel);

    // Rear panels and fins
    const rearPanelGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.6);
    const rearPanel = new THREE.Mesh(rearPanelGeometry, texturedMaterial);
    rearPanel.position.x = -size * 0.4;
    rearPanel.rotation.y = Math.PI;
    shipGroup.add(rearPanel);
    const rearFinGeometry = new THREE.PlaneGeometry(size * 0.3, size * 0.2);
    const topRearFin = new THREE.Mesh(rearFinGeometry, texturedMaterial);
    topRearFin.position.set(-size * 0.5, size * 0.15, 0);
    topRearFin.rotation.set(-Math.PI / 3, 0, 0);
    shipGroup.add(topRearFin);
    const bottomRearFin = new THREE.Mesh(rearFinGeometry, texturedMaterial);
    bottomRearFin.position.set(-size * 0.5, -size * 0.15, 0);
    bottomRearFin.rotation.set(Math.PI / 3, 0, 0);
    shipGroup.add(bottomRearFin);

    // Position the entire ship
    shipGroup.position.set(ship.pos.x, ship.pos.y, ship.pos.z);
    return shipGroup;
  };

  // If we already have an asset in pool, build textured ship from it
  try {
    if (pool && pool.has(svgUrl)) {
      const svgAsset = pool.get(svgUrl);
      if (svgAsset?.imageBitmap) return createTextured3DShip(svgAsset.imageBitmap);
    }
  } catch (_e) { void _e;/* ignore */ }

  // Fallback placeholder, and kick off async load to replace visual when ready
  const geom = new THREE.ConeGeometry(8, 24, 8);
  const mat = new THREE.MeshPhongMaterial({ 
    color: colorForTeam(ship.team), 
    emissive: 0x111122 
  });
  const placeholder = new THREE.Mesh(geom, mat);
  placeholder.rotation.z = 0; // Will be set correctly in updateTransforms
  placeholder.position.set(ship.pos.x, ship.pos.y, ship.pos.z);

  // Lazy-load SVG and swap geometry/material once available
  (async () => {
    try {
      const teamColor = ship.team === 'red' ? defaultSVGConfig.teamColors.red : defaultSVGConfig.teamColors.blue;
      const asset = await loadSVGAsset(svgUrl, {
        width: defaultSVGConfig.defaultRasterSize.width,
        height: defaultSVGConfig.defaultRasterSize.height,
        teamColor: teamColor
      });
      if (pool) pool.set(svgUrl, asset);
      if (asset?.imageBitmap && placeholder.parent) {
        // Build a representative list of geometries and materials matching the textured ship parts.
        try {
          const teamColor = ship.team === 'red' ? 0xff4444 : 0x4444ff;
          const texturedMaterial = new THREE.MeshBasicMaterial({ map: new THREE.Texture(asset.imageBitmap), transparent: true, alphaTest: 0.05, side: THREE.DoubleSide });
          texturedMaterial.map!.needsUpdate = true;
          const teamMaterial = new THREE.MeshBasicMaterial({ color: teamColor, transparent: true, opacity: 0.8, side: THREE.DoubleSide });

          const size = ShipVisualConfig.ships[ship.class]?.collisionRadius ?? RendererConfig.defaultCollisionRadius;
          const bodyGeometry = new THREE.CylinderGeometry(size * 0.3, size * 0.4, size * 0.8, 8);
          const noseGeometry = new THREE.ConeGeometry(size * 0.3, size * 0.5, 8);
          const wingGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.4);
          const sidePanelGeometry = new THREE.PlaneGeometry(size * 0.8, size * 0.3);
          const rearPanelGeometry = new THREE.PlaneGeometry(size * 0.6, size * 0.6);
          const rearFinGeometry = new THREE.PlaneGeometry(size * 0.3, size * 0.2);

          const geoms = [bodyGeometry, noseGeometry, wingGeometry, wingGeometry, sidePanelGeometry, sidePanelGeometry, rearPanelGeometry, rearFinGeometry, rearFinGeometry];
          const mats = [texturedMaterial, teamMaterial, texturedMaterial, texturedMaterial, texturedMaterial, texturedMaterial, texturedMaterial, texturedMaterial, texturedMaterial];

          // Register prototype for the instancer so future ships of this class can use instancing.
          shipInstancer.registerPrototype(ship.class, geoms, mats);

          // If instancing is enabled and we can allocate for this existing ship, migrate the placeholder
          // to an instanced slot instead of adding a non-instanced textured mesh.
          if (RendererConfig.instancing.enableShips) {
            try {
              const allocated = shipInstancer.allocate(ship.id, ship.class, ship.team);
              if (allocated) {
                // Immediately set transform so the instance appears in the correct place
                const q = new THREE.Quaternion();
                q.setFromEuler(new THREE.Euler(ship.orientation.pitch, ship.orientation.yaw - Math.PI/2, ship.orientation.roll));
                const scale = ShipVisualConfig.ships[ship.class]?.scale ?? RendererConfig.defaultScale;
                shipInstancer.updateTransform(ship.id, ship.pos, q, scale);
                // Remove placeholder from scene and track a lightweight object in the mesh map
                try { if (placeholder.parent) placeholder.parent.remove(placeholder); } catch (_e) { void _e;/* ignore */ }
                shipMeshes.set(ship.id, new THREE.Object3D());
                // Don't add the textured non-instanced mesh
                return;
              }
            } catch (e) { void e;logger.warn('shipInstancer.allocate during migration failed', e as any);
            }
          }

          // Fallback: create full textured mesh and replace placeholder
          const ship3D = createTextured3DShip(asset.imageBitmap);
          ship3D.position.copy(placeholder.position);
          shipsGroup.add(ship3D);
          shipsGroup.remove(placeholder);
          shipMeshes.set(ship.id, ship3D);
        } catch (e) { void e;logger.warn('shipInstancer.allocate during migration failed', e as any);
          logger.warn('shipInstancer.registerPrototype or migration failed', e as any);
          const ship3D = createTextured3DShip(asset.imageBitmap);
          ship3D.position.copy(placeholder.position);
          shipsGroup.add(ship3D);
          shipsGroup.remove(placeholder);
          shipMeshes.set(ship.id, ship3D);
        }
      }
    } catch (e) { void e;// Loading/parsing of SVG failed — log and keep placeholder
      logger.error('Failed to load SVG asset for ship', e);
    }
  })();

  // Return placeholder while async asset loads
  return placeholder;
}

/**
 * Creates a mesh for a bullet
 */
export function createBulletMesh(bullet: Bullet): THREE.Object3D {
  const geom = new THREE.SphereGeometry(2.2, 8, 8);
  const mat = new THREE.MeshBasicMaterial({ color: 0xffdd88 });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.set(bullet.pos.x, bullet.pos.y, bullet.pos.z);
  return mesh;
}

/**
 * Creates a health bar mesh with background, health, and shield components
 */
export function createHealthBarMesh(ship: Ship, factoryState: MeshFactoryState): THREE.Object3D {
  const config = RendererConfig.healthBars;
  const barGroup = new THREE.Group();

  // Background bar
  const bgGeom = new THREE.PlaneGeometry(config.width, config.position.height);
  let bgMat: THREE.Material;
  if (factoryState.GPU_BILLBOARD) {
    const mat = getPooledBillboardMaterial(new THREE.Color(config.colors.background), 1.0, factoryState);
    bgMat = mat;
  } else {
    bgMat = new THREE.MeshBasicMaterial({ color: config.colors.background });
  }
  const bgMesh = new THREE.Mesh(bgGeom, bgMat);
  barGroup.add(bgMesh);

  // Health bar
  const healthGeom = new THREE.PlaneGeometry(config.width - 2, config.position.height - 2);
  let healthMat: THREE.Material;
  if (factoryState.GPU_BILLBOARD) {
    const mat = getPooledBillboardMaterial(new THREE.Color(config.colors.health.full), 1.0, factoryState);
    healthMat = mat;
  } else {
    healthMat = new THREE.MeshBasicMaterial({ color: config.colors.health.full });
  }
  const healthMesh = new THREE.Mesh(healthGeom, healthMat);
  barGroup.add(healthMesh);

  // Shield bar (if ship has shield)
  let shieldMesh: THREE.Mesh | null = null;
  if (ship.maxShield > 0) {
    const shieldGeom = new THREE.PlaneGeometry(config.width - 2, config.position.height - 2);
    let shieldMat: THREE.Material;
    if (factoryState.GPU_BILLBOARD) {
      const mat = getPooledBillboardMaterial(new THREE.Color(config.colors.shield.full), 0.8, factoryState);
      shieldMat = mat;
    } else {
      shieldMat = new THREE.MeshBasicMaterial({ color: config.colors.shield.full, transparent: true, opacity: 0.8 });
    }
    shieldMesh = new THREE.Mesh(shieldGeom, shieldMat);
    shieldMesh.position.z = 0.1; // slightly in front
    barGroup.add(shieldMesh);
  }

  // Border
  const borderGeom = new THREE.RingGeometry(config.width/2 - config.border.width/2, config.width/2 + config.border.width/2, 8);
  const borderMat = new THREE.MeshBasicMaterial({ color: config.border.color, transparent: true, opacity: 0.5 });
  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = 0.2;
  barGroup.add(borderMesh);

  // Store references for updating
  (barGroup as any).healthMesh = healthMesh;
  (barGroup as any).shieldMesh = shieldMesh;
  (barGroup as any).bgMesh = bgMesh;

  return barGroup;
}

/**
 * Updates the health bar mesh based on ship status
 */
export function updateHealthBarMesh(ship: Ship, barGroup: THREE.Object3D): void {
  const config = RendererConfig.healthBars;
  const healthMesh = (barGroup as any).healthMesh as THREE.Mesh;
  const shieldMesh = (barGroup as any).shieldMesh as THREE.Mesh | null;

  // Position the bar above the ship (3D)
  barGroup.position.set(
    ship.pos.x + config.position.offsetX,
    ship.pos.y + config.position.offsetY,
    ship.pos.z + ShipVisualConfig.healthBar.offset.z // Above the ship
  );

  // Update health bar
  const healthPercent = ship.health / ship.maxHealth;
  healthMesh.scale.x = Math.max(0, healthPercent);

  // Update health color based on percentage
  const healthColor = healthPercent > 0.5 ? config.colors.health.full : config.colors.health.damaged;
  if (healthMesh.material) {
    const mat = (healthMesh.material as any) as THREE.ShaderMaterial;
    if (mat.uniforms && mat.uniforms.uColor) {
      (mat.uniforms.uColor.value as THREE.Color).set(healthColor);
    } else if ((healthMesh.material as THREE.MeshBasicMaterial).color) {
      (healthMesh.material as THREE.MeshBasicMaterial).color.set(healthColor);
    }
  }

  // Update shield bar
  if (shieldMesh && ship.maxShield > 0) {
    const shieldPercent = ship.shield / ship.maxShield;
    shieldMesh.scale.x = Math.max(0, shieldPercent);

    const shieldColor = shieldPercent > 0.5 ? config.colors.shield.full : config.colors.shield.damaged;
    if (shieldMesh.material) {
      const mat = (shieldMesh.material as any) as THREE.ShaderMaterial;
      if (mat.uniforms && mat.uniforms.uColor) {
        (mat.uniforms.uColor.value as THREE.Color).set(shieldColor);
      } else if ((shieldMesh.material as THREE.MeshBasicMaterial).color) {
        (shieldMesh.material as THREE.MeshBasicMaterial).color.set(shieldColor);
      }
    }
  }
}

/**
 * Get or create a pooled ShaderMaterial for the given color/alpha
 */
export function getPooledBillboardMaterial(
  color: THREE.Color = new THREE.Color(0xffffff), 
  alpha: number = 1.0,
  factoryState: MeshFactoryState
): THREE.ShaderMaterial {
  const key = billboardPoolKey(color, alpha);
  const existing = factoryState.billboardMaterialPool.get(key);
  if (existing) return existing;

  const mat = new THREE.ShaderMaterial({
    uniforms: {
      cameraRight: { value: new THREE.Vector3(1, 0, 0) },
      cameraUp: { value: new THREE.Vector3(0, 1, 0) },
      uColor: { value: color.clone() },
      uAlpha: { value: alpha },
    },
    vertexShader: billboardVertexShader,
    fragmentShader: billboardFragmentShader,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });
  factoryState.billboardMaterialPool.set(key, mat);
  factoryState.billboardMaterials.add(mat);
  return mat;
}

/**
 * Helper: compute a key for the material pool based on color and alpha
 */
function billboardPoolKey(color: THREE.Color, alpha: number): string {
  // Use CSS hex + alpha to key materials
  return `${color.getHexString()}|${alpha}`;
}

/**
 * Billboard shader: place quad in world space using camera right/up vectors so it always faces the camera.
 */
const billboardVertexShader = `
  uniform vec3 cameraRight;
  uniform vec3 cameraUp;
  uniform float uAlpha;
  uniform vec3 uColor;

  varying vec3 vColor;
  varying float vAlpha;

  void main() {
    // center of this object in world-space
    vec3 center = (modelMatrix * vec4(0.0, 0.0, 0.0, 1.0)).xyz;
    // position.xy are the local quad coords (e.g., -w/2..w/2, -h/2..h/2)
    vec3 worldPos = center + cameraRight * position.x + cameraUp * position.y;
    gl_Position = projectionMatrix * viewMatrix * vec4(worldPos, 1.0);
    vColor = uColor;
    vAlpha = uAlpha;
  }
`;

const billboardFragmentShader = `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    gl_FragColor = vec4(vColor, vAlpha);
  }
`;

/**
 * Helper function to get team color
 */
function colorForTeam(team: 'red' | 'blue'): number {
  return team === 'red' ? 0xff5050 : 0x50a0ff;
}

/**
 * Disposes mesh factory resources
 */
export function disposeMeshFactory(factoryState: MeshFactoryState): void {
  // Dispose pooled billboard materials
  for (const mat of factoryState.billboardMaterialPool.values()) {
    try { 
      mat.dispose(); 
    } catch (_e) { void _e;/* ignore */ 
    }
  }
  factoryState.billboardMaterialPool.clear();
  factoryState.billboardMaterials.clear();
}

/**
 * Default mesh factory implementation
 */
export const meshFactory: MeshFactory = {
  createShipMesh,
  createBulletMesh,
  createHealthBarMesh,
  updateHealthBarMesh,
  getPooledBillboardMaterial,
  disposeMeshFactory
};

import * as THREE from 'three';
import type { CameraState } from './cameraManager.js';
