import * as THREE from 'three';
import type { GameState } from '../types/index.js';
import { RendererEffectsConfig } from '../config/rendererEffectsConfig.js';
import { RendererConfig } from '../config/rendererConfig.js';
import { skyboxVertexShader, skyboxFragmentShader } from './shaders/skyboxShader.js';
import * as logger from '../utils/logger.js';

/**
 * Scene setup and lifecycle management
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface SceneElements {
  scene: THREE.Scene;
  ambientLight: THREE.AmbientLight;
  directionalLight: THREE.DirectionalLight;
  boundaryWireframe: THREE.LineSegments;
  skybox: THREE.Mesh;
  skyboxShaderMaterial: THREE.ShaderMaterial;
  staticSkyboxTexture: THREE.Texture;
  // Backwards-compatible fields used by older tests
  animatedSkyboxTexture?: THREE.CubeTexture;
  skyboxCanvases?: HTMLCanvasElement[];
  skyboxTextures?: THREE.CanvasTexture[];
}

export interface SceneManager {
  setupScene(state: GameState): SceneElements;
  updateSkyboxAnimation(elements: SceneElements, dt: number): void;
  disposeScene(elements: SceneElements): void;
}

/**
 * Creates and configures the basic scene elements
 */
export function setupScene(state: GameState): SceneElements {
  const scene = new THREE.Scene();
  
  // Create shader-based animated skybox
  const { skybox, skyboxShaderMaterial, staticSkyboxTexture } = createShaderBasedSkybox();
  scene.add(skybox);
  // Create backwards-compatible cube texture and canvas list used by some tests
  const skyboxCanvases: HTMLCanvasElement[] = [];
  const skyboxTextures: THREE.CanvasTexture[] = [];
  try {
    for (let i = 0; i < 6; i++) {
      const canvas = (staticSkyboxTexture.image as HTMLCanvasElement) || document.createElement('canvas');
      skyboxCanvases.push(canvas);
      const tex = new THREE.CanvasTexture(canvas);
      tex.generateMipmaps = false;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      skyboxTextures.push(tex);
    }
  } catch {
    // ignore - test environments may not support canvas
  }
  const animatedCube = new THREE.CubeTexture(skyboxCanvases as any);
  animatedCube.needsUpdate = true;
  
  // Add lighting
  const ambientLight = new THREE.AmbientLight(
    RendererEffectsConfig.lighting.ambient.color,
    RendererEffectsConfig.lighting.ambient.intensity
  );
  scene.add(ambientLight);

  const directionalLight = new THREE.DirectionalLight(
    RendererEffectsConfig.lighting.directional.color,
    RendererEffectsConfig.lighting.directional.intensity
  );
  directionalLight.position.set(
    RendererEffectsConfig.lighting.directional.position.x,
    RendererEffectsConfig.lighting.directional.position.y,
    RendererEffectsConfig.lighting.directional.position.z
  );
  scene.add(directionalLight);

  // Create boundary wireframe
  const boundaryWireframe = createBoundaryWireframe(state);
  scene.add(boundaryWireframe);

  return {
    scene,
    ambientLight,
    directionalLight,
    boundaryWireframe,
    skybox,
    skyboxShaderMaterial,
    staticSkyboxTexture,
    animatedSkyboxTexture: animatedCube,
    skyboxCanvases,
    skyboxTextures
  };
}

/**
 * Updates the shader-based animated skybox
 * Now GPU-based instead of CPU texture manipulation
 */
let skyboxAnimationTime = 0;
export function updateSkyboxAnimation(elements: SceneElements, dt: number): void {
  skyboxAnimationTime += dt;
  
  // Update shader uniforms for GPU-based animation
  if (elements.skyboxShaderMaterial && elements.skyboxShaderMaterial.uniforms) {
    elements.skyboxShaderMaterial.uniforms.time.value = skyboxAnimationTime;
  }
}

/**
 * Disposes scene resources
 */
export function disposeScene(elements: SceneElements): void {
  // Dispose textures
  elements.staticSkyboxTexture?.dispose();
  
  // Dispose shader material
  elements.skyboxShaderMaterial?.dispose();
  
  // Dispose geometries and materials
  elements.boundaryWireframe.geometry?.dispose();
  if (Array.isArray(elements.boundaryWireframe.material)) {
    elements.boundaryWireframe.material.forEach(mat => mat.dispose());
  } else {
    elements.boundaryWireframe.material?.dispose();
  }

  if (elements.skybox.geometry) elements.skybox.geometry.dispose();
  if (elements.skybox.material) {
    if (Array.isArray(elements.skybox.material)) {
      elements.skybox.material.forEach(mat => mat.dispose());
    } else {
      elements.skybox.material.dispose();
    }
  }

  // Clear the scene
  elements.scene.clear();
}

/**
 * Creates the boundary wireframe for the simulation bounds
 */
function createBoundaryWireframe(state: GameState): THREE.LineSegments {
  const boxGeom = new THREE.BoxGeometry(
    state.simConfig.simBounds.width,
    state.simConfig.simBounds.height,
    state.simConfig.simBounds.depth
  );
  const edges = new THREE.EdgesGeometry(boxGeom);
  const lineMat = new THREE.LineBasicMaterial({
    color: RendererEffectsConfig.worldBoundaries.color,
    transparent: true,
    opacity: RendererEffectsConfig.worldBoundaries.opacity
  });
  const boxWire = new THREE.LineSegments(edges, lineMat);
  boxWire.position.set(
    state.simConfig.simBounds.width / 2,
    state.simConfig.simBounds.height / 2,
    state.simConfig.simBounds.depth / 2
  );
  
  boxGeom.dispose(); // Clean up intermediate geometry
  
  return boxWire;
}

/**
 * Creates the shader-based animated skybox with GPU-based star twinkling
 * Performance optimization: moves animation from CPU to GPU
 */
function createShaderBasedSkybox(): {
  skybox: THREE.Mesh;
  skyboxShaderMaterial: THREE.ShaderMaterial;
  staticSkyboxTexture: THREE.Texture;
} {
  // Generate static starfield texture (done once, not animated on CPU)
  const staticTexture = generateStaticStarfieldTexture();
  
  // Create shader material with GPU-based animation
  const skyboxShaderMaterial = new THREE.ShaderMaterial({
    uniforms: {
      time: { value: 0.0 },
      twinkleSpeed: { value: RendererEffectsConfig.skybox.starfield.animation.twinkleSpeed },
      starfieldTexture: { value: staticTexture },
      baseColor: { value: new THREE.Vector3(0.0, 0.05, 0.2) } // Deep space blue
    },
    vertexShader: skyboxVertexShader,
    fragmentShader: skyboxFragmentShader,
    side: THREE.BackSide,
    depthWrite: false,
    depthTest: false
  });

  // Create sphere geometry for skybox
  const skyboxGeometry = new THREE.SphereGeometry(
    RendererEffectsConfig.skybox.sphere.radius,
    RendererEffectsConfig.skybox.sphere.geometrySegments,
    RendererEffectsConfig.skybox.sphere.geometrySegments
  );

  const skybox = new THREE.Mesh(skyboxGeometry, skyboxShaderMaterial);

  return {
    skybox,
    skyboxShaderMaterial,
    staticSkyboxTexture: staticTexture
  };
}

/**
 * Generates a static starfield texture (no animation, just the base pattern)
 */
function generateStaticStarfieldTexture(): THREE.Texture {
  const textureSize = RendererEffectsConfig.skybox.starfield.textureSize;
  const canvas = document.createElement('canvas');
  canvas.width = textureSize;
  canvas.height = textureSize;
  const ctx = canvas.getContext('2d');

  // Handle test environment where canvas context might not be available
  if (!ctx) {
    logger.warn('Canvas 2D context not available, creating fallback texture');
    // Create a simple colored texture as fallback
    const fallbackCanvas = document.createElement('canvas');
    fallbackCanvas.width = 32;
    fallbackCanvas.height = 32;
    const texture = new THREE.CanvasTexture(fallbackCanvas);
    texture.generateMipmaps = false;
    texture.minFilter = THREE.LinearFilter;
    texture.magFilter = THREE.LinearFilter;
    return texture;
  }

  // Create gradient background
  const gradient = ctx.createRadialGradient(
    textureSize/2, textureSize/2, 0, 
    textureSize/2, textureSize/2, textureSize/2
  );
  gradient.addColorStop(0, '#001122');
  gradient.addColorStop(0.5, '#000811');
  gradient.addColorStop(1, '#000000');
  
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, textureSize, textureSize);

  // Generate static stars (no animation)
  const seed = RendererEffectsConfig.skybox.starfield.baseSeed;
  let currentSeed = seed;
  const random = () => {
    currentSeed = (currentSeed * 9301 + 49297) % 233280;
    return currentSeed / 233280;
  };

  const starCount = RendererEffectsConfig.skybox.starfield.starCounts.sides;
  const starColors = ['#ffffff', '#e6e6ff', '#ccccff', '#b3b3ff', '#9999ff'];

  for (let i = 0; i < starCount; i++) {
    const x = random() * textureSize;
    const y = random() * textureSize;
    const size = random() < 0.7 ? 1 : random() < 0.9 ? 2 : 3;
    const brightness = random();
    const color = starColors[Math.floor(random() * starColors.length)];

    ctx.fillStyle = color;
    ctx.globalAlpha = 0.3 + brightness * 0.7;
    ctx.fillRect(x - size/2, y - size/2, size, size);
  }

  // Add nebula clouds
  if (random() < 0.3) {
    for (let i = 0; i < RendererEffectsConfig.skybox.starfield.nebula.count; i++) {
      const nebulaX = random() * textureSize;
      const nebulaY = random() * textureSize;
      const nebulaRadius = RendererEffectsConfig.skybox.starfield.nebula.minRadius + 
        random() * RendererEffectsConfig.skybox.starfield.nebula.maxRadius;
      
      const nebulaGradient = ctx.createRadialGradient(nebulaX, nebulaY, 0, nebulaX, nebulaY, nebulaRadius);
      nebulaGradient.addColorStop(0, `rgba(${100 + random() * 100}, ${50 + random() * 100}, ${150 + random() * 100}, ${0.1 + random() * 0.2})`);
      nebulaGradient.addColorStop(0.5, `rgba(${50 + random() * 100}, ${25 + random() * 75}, ${100 + random() * 100}, ${0.05 + random() * 0.1})`);
      nebulaGradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
      
      ctx.fillStyle = nebulaGradient;
      ctx.globalAlpha = 1;
      ctx.beginPath();
      ctx.arc(nebulaX, nebulaY, nebulaRadius, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.globalAlpha = 1;

  // Create texture from canvas
  const texture = new THREE.CanvasTexture(canvas);
  texture.generateMipmaps = false;
  texture.minFilter = THREE.LinearFilter;
  texture.magFilter = THREE.LinearFilter;
  texture.wrapS = THREE.RepeatWrapping;
  texture.wrapT = THREE.RepeatWrapping;

  return texture;
}



/**
 * Default scene manager implementation
 */
export const sceneManager: SceneManager = {
  setupScene,
  updateSkyboxAnimation,
  disposeScene
};

import * as THREE from 'three';

type Float3 = { x: number; y: number; z: number };

type GroupData = {
  className: string;
  team?: string;
  meshes: THREE.InstancedMesh[];
  capacity: number;
  freeIndices: number[];
  idToIndex: Map<number, number>;
  indexToId: Map<number, number>;
  matricesNeedUpdate: boolean;
  prototypeGeometries: THREE.BufferGeometry[];
  prototypeMaterials: THREE.Material[];
  parentGroup: THREE.Group;
};

class ShipInstancerImpl {
  private scene?: THREE.Scene;
  private rootParent?: THREE.Group;
  // Readiness signalling
  public isReady = false;
  private readyCallbacks: Array<() => void> = [];
  private groups = new Map<string, GroupData>();
  private defaultCapacity = 64;
  private growthFactor = 1.5;
  private fallbackGeometry?: THREE.BufferGeometry;
  private fallbackMaterial?: THREE.MeshStandardMaterial;

  private prototypeRegistry = new Map<string, { geometries: THREE.BufferGeometry[]; materials: THREE.Material[] }>();

  init(scene: THREE.Scene, parent: THREE.Group) {
    this.scene = scene;
    this.rootParent = parent;
    if (!this.fallbackGeometry) this.fallbackGeometry = new THREE.ConeGeometry(0.4, 1.4, 6);
    if (!this.fallbackMaterial) this.fallbackMaterial = new THREE.MeshStandardMaterial({ color: 0x8888ff });
  }

  onReady(cb: () => void): void {
    if (this.isReady) {
      try { cb(); } catch (_) { void _;/* no-op */ }
      return;
    }
    this.readyCallbacks.push(cb);
  }

  registerPrototype(className: string, geometries: THREE.BufferGeometry | THREE.BufferGeometry[], materials?: THREE.Material | THREE.Material[]) {
    const geoms = Array.isArray(geometries) ? geometries : [geometries];
    const mats = materials ? (Array.isArray(materials) ? materials : [materials]) : geoms.map(() => this.fallbackMaterial!.clone());
    const padded = mats.length < geoms.length ? [...mats, ...Array(geoms.length - mats.length).fill(mats[mats.length - 1].clone())] : mats.slice(0, geoms.length);
    this.prototypeRegistry.set(className, { geometries: geoms, materials: padded });
    // If init() has already been called and this is the first prototype,
    // mark the instancer as ready so consumers can switch to instanced paths.
    if (!this.isReady && this.rootParent) {
      this.isReady = true;
      for (const cb of this.readyCallbacks) {
        try { cb(); } catch (_e) { void _e;/* ignore callback errors */ }
      }
      this.readyCallbacks.length = 0;
    }
  }

  allocate(shipId: number, className: string, team?: string): boolean {
    if (!this.scene || !this.rootParent) return false;
    let group = this.groups.get(className);
    if (!group) {
      group = this.createGroup(className, team);
      this.groups.set(className, group);
    }
    if (group.idToIndex.has(shipId)) return true;
    if (group.freeIndices.length === 0) this.growGroup(group);
    const idx = group.freeIndices.pop();
    if (idx === undefined) return false;
    group.idToIndex.set(shipId, idx);
    group.indexToId.set(idx, shipId);
    const identity = new THREE.Matrix4();
    for (const m of group.meshes) m.setMatrixAt(idx, identity);
    group.matricesNeedUpdate = true;
    return true;
  }

  free(shipId: number): boolean {
    for (const group of this.groups.values()) {
      if (group.idToIndex.has(shipId)) {
        const idx = group.idToIndex.get(shipId)!;
        group.idToIndex.delete(shipId);
        group.indexToId.delete(idx);
        group.freeIndices.push(idx);
        const clear = new THREE.Matrix4(); clear.makeScale(0, 0, 0);
        for (const m of group.meshes) m.setMatrixAt(idx, clear);
        group.matricesNeedUpdate = true;
        return true;
      }
    }
    return false;
  }

  hasShip(shipId: number): boolean { for (const g of this.groups.values()) if (g.idToIndex.has(shipId)) return true; return false; }

  updateTransform(shipId: number, pos: Float3, quat: THREE.Quaternion, scale: number): boolean {
    for (const g of this.groups.values()) {
      const idx = g.idToIndex.get(shipId);
      if (idx === undefined) continue;
      const m = new THREE.Matrix4();
      m.compose(new THREE.Vector3(pos.x, pos.y, pos.z), quat, new THREE.Vector3(scale, scale, scale));
      for (const mesh of g.meshes) mesh.setMatrixAt(idx, m);
      g.matricesNeedUpdate = true;
      return true;
    }
    return false;
  }

  markMatricesNeedUpdate() { for (const g of this.groups.values()) g.matricesNeedUpdate = true; }

  sync() { for (const g of this.groups.values()) { if (!g.matricesNeedUpdate) continue; for (const m of g.meshes) m.instanceMatrix.needsUpdate = true; g.matricesNeedUpdate = false; } }

  dispose() {
    for (const g of this.groups.values()) {
      for (const m of g.meshes) {
        try { m.geometry.dispose(); } catch (_) { void _;/* no-op */ }
        try { if (Array.isArray(m.material)) (m.material as any).forEach((x: any) => x.dispose()); else (m.material as any).dispose(); } catch (_) { void _;/* no-op */ }
        try { if (m.parent) m.parent.remove(m); } catch (_) { void _;/* no-op */ }
      }
      try { if (g.parentGroup && g.parentGroup.parent) g.parentGroup.parent.remove(g.parentGroup); } catch (_) { void _;/* no-op */ }
    }
    this.groups.clear();
  }

  getStats() {
    const out: Record<string, { capacity: number; used: number; meshes: number }> = {};
    for (const [k, g] of this.groups.entries()) out[k] = { capacity: g.capacity, used: g.idToIndex.size, meshes: g.meshes.length };
    return { totalGroups: this.groups.size, groups: out };
  }

  private createGroup(className: string, team?: string): GroupData {
    const proto = this.prototypeRegistry.get(className);
    const geoms = proto ? proto.geometries : [this.fallbackGeometry!.clone()];
    const mats = proto ? proto.materials : [this.fallbackMaterial!.clone()];
    const capacity = this.defaultCapacity;
    const parentGroup = new THREE.Group();
    parentGroup.name = `ShipInstancer_${className}_group`;
    if (this.rootParent) this.rootParent.add(parentGroup);
    const meshes = geoms.map((g, i) => {
      const mat = (mats[i] || mats[0]).clone();
      const im = new THREE.InstancedMesh(g, mat, capacity);
      im.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      im.name = `Instanced_${className}_submesh_${i}`;
      im.frustumCulled = true;
      parentGroup.add(im);
      return im;
    });
    const free: number[] = [];
    for (let i = capacity - 1; i >= 0; i--) free.push(i);
    const group: GroupData = {
      className,
      team,
      meshes,
      capacity,
      freeIndices: free,
      idToIndex: new Map(),
      indexToId: new Map(),
      matricesNeedUpdate: false,
      prototypeGeometries: geoms.slice(),
      prototypeMaterials: mats.slice(),
      parentGroup,
    };
    // If this is the first created group and the instancer hasn't signaled ready,
    // mark it ready now so consumers relying on createGroup can begin using instanced paths.
    if (!this.isReady) {
      this.isReady = true;
      for (const cb of this.readyCallbacks) {
        try { cb(); } catch (_e) { void _e;/* ignore */ }
      }
      this.readyCallbacks.length = 0;
    }
    return group;
  }

  private growGroup(group: GroupData) {
    const oldCap = group.capacity;
    const newCap = Math.max(Math.ceil(oldCap * this.growthFactor), oldCap + 1);
    const newMeshes: THREE.InstancedMesh[] = [];
    for (let i = 0; i < group.prototypeGeometries.length; i++) {
      const geom = group.prototypeGeometries[i];
      const mat = (group.prototypeMaterials[i] || group.prototypeMaterials[0]).clone();
      const newMesh = new THREE.InstancedMesh(geom, mat, newCap);
      newMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
      newMesh.name = `${group.className}_grown_submesh_${i}`;
      newMesh.frustumCulled = true;
      const oldMesh = group.meshes[i];
      const tmp = new THREE.Matrix4();
      for (let idx = 0; idx < oldCap; idx++) { oldMesh.getMatrixAt(idx, tmp); newMesh.setMatrixAt(idx, tmp); }
      group.parentGroup.add(newMesh);
      newMeshes.push(newMesh);
    }
    for (const old of group.meshes) { try { if (old.parent) old.parent.remove(old); } catch (_) { void _;/* no-op */ } }
    group.meshes = newMeshes;
    for (let i = newCap - 1; i >= oldCap; i--) group.freeIndices.push(i);
    group.capacity = newCap;
    group.matricesNeedUpdate = true;
  }
}

const impl = new ShipInstancerImpl();

export const shipInstancer = {
  init: (scene: THREE.Scene, parent: THREE.Group) => impl.init(scene, parent),
  onReady: (cb: () => void) => impl.onReady(cb),
  registerPrototype: (className: string, geometries: THREE.BufferGeometry | THREE.BufferGeometry[], materials?: THREE.Material | THREE.Material[]) => impl.registerPrototype(className, geometries, materials),
  allocate: (shipId: number, className: string, team?: string) => impl.allocate(shipId, className, team),
  free: (shipId: number) => impl.free(shipId),
  hasShip: (shipId: number) => impl.hasShip(shipId),
  updateTransform: (shipId: number, pos: { x: number; y: number; z: number }, quat: THREE.Quaternion, scale: number) => impl.updateTransform(shipId, pos, quat, scale),
  markMatricesNeedUpdate: () => impl.markMatricesNeedUpdate(),
  sync: () => impl.sync(),
  dispose: () => impl.dispose(),
  getStats: () => impl.getStats(),
  isReady: () => impl.isReady,
} as const;

import * as THREE from 'three';
import type { GameState, Ship, Bullet } from '../types/index.js';
import { RendererConfig } from '../config/rendererConfig.js';
import { ShipVisualConfig } from '../config/shipVisualConfig.js';
import type { MeshFactoryState } from './meshFactory.js';
import type { ShieldEffectState } from './effects/shieldEffect.js';
import type { HealthBarInstancer } from './healthBarInstancer.js';

/**
 * Entity synchronizer - maps GameState to Three.js scene objects
 * Extracted from threeRenderer.ts for SRP compliance
 */

export interface SynchronizerState {
  shipMeshes: Map<number, THREE.Object3D>;
  bulletMeshes: Map<number, THREE.Object3D>;
  healthBarMeshes: Map<number, THREE.Object3D>;
  shieldEffectMeshes: Map<number, THREE.Object3D>;
}

export interface SynchronizerGroups {
  shipsGroup: THREE.Group;
  bulletsGroup: THREE.Group;
  healthBarsGroup: THREE.Group;
  shieldEffectsGroup: THREE.Group;
}

export interface Synchronizer {
  createSynchronizerState(): SynchronizerState;
  createSynchronizerGroups(): SynchronizerGroups;
  syncEntities(
    state: GameState, 
    syncState: SynchronizerState, 
    groups: SynchronizerGroups,
    meshFactory: any,
    shieldEffect: any,
    meshFactoryState: MeshFactoryState,
    shieldEffectState: ShieldEffectState,
    camera?: THREE.Camera,
    healthBarInstancer?: HealthBarInstancer
  ): void;
  updateTransforms(
    state: GameState, 
    syncState: SynchronizerState,
    meshFactory: any,
    shieldEffect: any,
    shieldEffectState: ShieldEffectState,
    camera?: THREE.Camera,
    healthBarInstancer?: HealthBarInstancer
  ): void;
  disposeSynchronizer(syncState: SynchronizerState): void;
}

/**
 * Creates the synchronizer state
 */
export function createSynchronizerState(): SynchronizerState {
  return {
    shipMeshes: new Map<number, THREE.Object3D>(),
    bulletMeshes: new Map<number, THREE.Object3D>(),
    healthBarMeshes: new Map<number, THREE.Object3D>(),
    shieldEffectMeshes: new Map<number, THREE.Object3D>()
  };
}

/**
 * Creates the Three.js groups for organizing entities
 */
export function createSynchronizerGroups(): SynchronizerGroups {
  return {
    shipsGroup: new THREE.Group(),
    bulletsGroup: new THREE.Group(),
    healthBarsGroup: new THREE.Group(),
    shieldEffectsGroup: new THREE.Group()
  };
}

/**
 * Synchronizes entities between GameState and Three.js scene
 */
export function syncEntities(
  state: GameState, 
  syncState: SynchronizerState, 
  groups: SynchronizerGroups,
  meshFactory: any,
  shieldEffect: any,
  meshFactoryState: MeshFactoryState,
  shieldEffectState: ShieldEffectState,
  camera?: THREE.Camera,
  healthBarInstancer?: HealthBarInstancer
): void {
  const useHealthBarInstancing = RendererConfig.instancing.enableBars && healthBarInstancer;

  // Update camera uniforms for health bar instancer if enabled
  if (useHealthBarInstancing && camera) {
    healthBarInstancer!.updateCameraUniforms(camera);
  }

  // Ships
  for (const s of state.ships) {
    if (!syncState.shipMeshes.has(s.id)) {
      const m = meshFactory.createShipMesh(s, state, groups.shipsGroup, syncState.shipMeshes);
      syncState.shipMeshes.set(s.id, m); 
      groups.shipsGroup.add(m);
    }
    
    // Health bars
    if (RendererConfig.visual.enableHealthBars) {
      if (useHealthBarInstancing) {
        // Use health bar instancer
        if (!healthBarInstancer!.hasShip(s.id)) {
          healthBarInstancer!.allocateInstance(s.id);
        }
      } else {
        // Use traditional mesh factory approach
        if (!syncState.healthBarMeshes.has(s.id)) {
          const bar = meshFactory.createHealthBarMesh(s, meshFactoryState);
          syncState.healthBarMeshes.set(s.id, bar); 
          groups.healthBarsGroup.add(bar);
        }
      }
    }
    
    // Shield effects
    if (RendererConfig.visual.enableShieldEffects && s.maxShield > 0 && !syncState.shieldEffectMeshes.has(s.id)) {
      const shield = shieldEffect.createShieldEffect(s, shieldEffectState);
      syncState.shieldEffectMeshes.set(s.id, shield); 
      groups.shieldEffectsGroup.add(shield);
    }
  }

  // Remove ships that no longer exist
  for (const [id, m] of syncState.shipMeshes) {
    if (!state.ships.find(s => s.id === id)) {
      groups.shipsGroup.remove(m); 
      syncState.shipMeshes.delete(id);
      
      // Also remove health bar
      if (useHealthBarInstancing) {
        healthBarInstancer!.freeInstance(id);
      } else {
        const bar = syncState.healthBarMeshes.get(id);
        if (bar) { 
          groups.healthBarsGroup.remove(bar); 
          syncState.healthBarMeshes.delete(id); 
        }
      }
      
      // Also remove shield effect
      const shield = syncState.shieldEffectMeshes.get(id);
      if (shield) { 
        shieldEffect.disposeShieldEffect(shield);
        groups.shieldEffectsGroup.remove(shield); 
        syncState.shieldEffectMeshes.delete(id); 
      }
    }
  }

  // Remove health bars for ships that no longer exist (non-instanced only)
  if (!useHealthBarInstancing) {
    for (const [id, bar] of syncState.healthBarMeshes) {
      if (!state.ships.find(s => s.id === id)) {
        groups.healthBarsGroup.remove(bar); 
        syncState.healthBarMeshes.delete(id);
      }
    }
  }

  // Remove shield effects for ships that no longer exist or have no shield
  for (const [id, shield] of syncState.shieldEffectMeshes) {
    const ship = state.ships.find(s => s.id === id);
    if (!ship || ship.maxShield <= 0) {
      shieldEffect.disposeShieldEffect(shield);
      groups.shieldEffectsGroup.remove(shield); 
      syncState.shieldEffectMeshes.delete(id);
    }
  }

  // Bullets
  for (const b of state.bullets) {
    if (!syncState.bulletMeshes.has(b.id)) {
      const m = meshFactory.createBulletMesh(b);
      syncState.bulletMeshes.set(b.id, m); 
      groups.bulletsGroup.add(m);
    }
  }

  // Remove bullets that no longer exist
  for (const [id, m] of syncState.bulletMeshes) {
    if (!state.bullets.find(b => b.id === id)) { 
      groups.bulletsGroup.remove(m); 
      syncState.bulletMeshes.delete(id); 
    }
  }

  // Mark instancer matrices as needing update
  if (useHealthBarInstancing) {
    healthBarInstancer!.markMatricesNeedUpdate();
  }
}

/**
 * Updates transform properties of all entities
 */
export function updateTransforms(
  state: GameState, 
  syncState: SynchronizerState,
  meshFactory: any,
  shieldEffect: any,
  shieldEffectState: ShieldEffectState,
  camera?: THREE.Camera,
  healthBarInstancer?: HealthBarInstancer
): void {
  // Use the simulation/game time so visuals driven from game state (e.g. lastShieldHitTime)
  // use the same timebase as the renderer uniforms. This prevents mismatches where
  // effects that rely on timestamps (hit times) would appear permanent or vanish.
  const currentTime = state.time; // seconds
  const useHealthBarInstancing = RendererConfig.instancing.enableBars && healthBarInstancer;
  
  // Update ships
  for (const s of state.ships) {
    const m = syncState.shipMeshes.get(s.id);
    if (!m) continue;
    
    m.position.set(s.pos.x, s.pos.y, s.pos.z);
    
    // Set 3D rotation using ship's orientation
    // Ships are modeled pointing along +X axis, so we need to adjust
    // Order: first yaw (Y-axis), then pitch (X-axis), then roll (Z-axis)
    m.rotation.set(s.orientation.pitch, s.orientation.yaw - Math.PI/2, s.orientation.roll);
    
    const scale = ShipVisualConfig.ships[s.class]?.scale ?? RendererConfig.defaultScale;
    m.scale.setScalar(scale);

    // Update health bar
    if (RendererConfig.visual.enableHealthBars) {
      if (useHealthBarInstancing) {
        // Update through health bar instancer
        healthBarInstancer!.updateHealthBar(s);
      } else {
        // Update through traditional mesh factory
        const bar = syncState.healthBarMeshes.get(s.id);
        if (bar) {
          meshFactory.updateHealthBarMesh(s, bar);
        }
      }
    }

    // Update shield effect
    if (RendererConfig.visual.enableShieldEffects && s.maxShield > 0) {
      const shield = syncState.shieldEffectMeshes.get(s.id);
      if (shield) {
        shieldEffect.updateShieldEffect(s, shield, currentTime, shieldEffectState);
      }
    }
  }

  // Update bullets
  for (const b of state.bullets) {
    const m = syncState.bulletMeshes.get(b.id);
    if (!m) continue;
    m.position.set(b.pos.x, b.pos.y, b.pos.z);
  }

  // Update health bar positions to follow ships (non-instanced only)
  if (!useHealthBarInstancing) {
    for (const s of state.ships) {
      const bar = syncState.healthBarMeshes.get(s.id);
      if (bar) {
        bar.position.set(
          s.pos.x + RendererConfig.healthBars.position.offsetX,
          s.pos.y + RendererConfig.healthBars.position.offsetY,
          s.pos.z + ShipVisualConfig.healthBar.offset.z // Above the ship
        );
      }
    }
  }

  // Mark instancer matrices as needing update
  if (useHealthBarInstancing) {
    healthBarInstancer!.markMatricesNeedUpdate();
  }
}

/**
 * Disposes synchronizer resources
 */
export function disposeSynchronizer(syncState: SynchronizerState): void {
  syncState.shipMeshes.clear();
  syncState.bulletMeshes.clear();
  syncState.healthBarMeshes.clear();
  syncState.shieldEffectMeshes.clear();
}

/**
 * Default synchronizer implementation
 */
export const synchronizer: Synchronizer = {
  createSynchronizerState,
  createSynchronizerGroups,
  syncEntities,
  updateTransforms,
  disposeSynchronizer
};

import type { GameState } from '../types/index.js';
import { createEffectsManager } from './effects.js';
import { createAnimationManager } from './animationManager.js';
import { createBVHManager } from './bvhManager.js';

export interface UnifiedEffectsManager {
  initDone: boolean;
  effects: import('./effects.js').EffectsManager;
  animation: import('./animationManager.js').AnimationManager;
  bvh: import('./bvhManager.js').BVHManager;

  // Unified methods
  update: (dt: number) => void;
  handleShipSpawn: (ship: any) => void;
  handleShipDestruction: (ship: any) => Promise<void>;
  handleExplosion: (position: { x: number; y: number; z: number }, intensity?: number) => Promise<void>;
  setQuality: (quality: 'low' | 'medium' | 'high') => void;
  dispose: () => void;
}

export function createUnifiedEffectsManager(state: GameState): UnifiedEffectsManager {
  // Create individual managers
  // Note: Effects manager will be created lazily when renderer is available
  let effects: import('./effects.js').EffectsManager | null = null;

  const animation = createAnimationManager(state);
  const bvh = createBVHManager(state);

  // Initialize effects manager when renderer becomes available
  function ensureEffectsManager() {
    if (!effects && state.renderer) {
      // We need to access the internal Three.js objects
      // This requires extending the renderer or accessing through a different method
      // For now, create a basic effects manager that can be enhanced later
      effects = {
        initDone: false,
        render: () => {},
        resize: () => {},
        dispose: () => {},
        setBloomIntensity: () => {},
        enableMotionBlur: () => {},
        enableDepthOfField: () => {},
        addExplosionEffect: () => {}
      };
    }
  }

  function update(dt: number) {
    ensureEffectsManager();

    // Update BVH with current ship positions
    bvh.updateBVH(state.ships);

    // Update effects
    if (effects && effects.initDone) {
      effects.render(dt);
    }
  }

  async function handleShipSpawn(ship: any) {
    if (animation.initDone && state.renderer) {
      animation.animateShipSpawn(ship, state.renderer);
    }
  }

  async function handleShipDestruction(ship: any): Promise<void> {
    if (animation.initDone && state.renderer) {
      await animation.animateShipDestruction(ship, state.renderer);
    }
  }

  async function handleExplosion(position: { x: number; y: number; z: number }, intensity = 1.0): Promise<void> {
    // Combine multiple effects for explosions
    const promises: Promise<void>[] = [];

    // Animation effects
    if (animation.initDone) {
      promises.push(animation.animateExplosion(position, intensity));
    }

    // Postprocessing effects
    if (effects && effects.initDone) {
      effects.addExplosionEffect(position, intensity);
    }

    // Camera shake
    if (animation.initDone) {
      animation.shakeCamera(intensity * 0.3, 0.4);
    }

    await Promise.all(promises);
  }

  function setQuality(quality: 'low' | 'medium' | 'high') {
    ensureEffectsManager();

    if (!effects) return;

    switch (quality) {
      case 'low':
        effects.setBloomIntensity(0.2);
        effects.enableMotionBlur(false);
        effects.enableDepthOfField(false);
        break;
      case 'medium':
        effects.setBloomIntensity(0.4);
        effects.enableMotionBlur(true);
        effects.enableDepthOfField(false);
        break;
      case 'high':
        effects.setBloomIntensity(0.6);
        effects.enableMotionBlur(true);
        effects.enableDepthOfField(true);
        break;
    }
  }

  // Ensure effects manager is initialized
